/**
 * Error model + a tiny Result type.
 *
 * Adapters do I/O and can fail in expected ways (binary missing, git rejects a
 * ref, GitHub is unreachable). Those are values, not exceptions: an adapter
 * returns `Result<T, BlastRadiusError>` and the caller decides. We still throw
 * for genuine programmer errors (a schema that can't parse our own fixtures).
 */

export type ErrorCode =
  | "BINARY_NOT_FOUND"
  | "GRAPH_ERROR"
  | "GIT_ERROR"
  | "INTENT_UNAVAILABLE"
  | "SINK_ERROR"
  | "CONFIG_ERROR"
  | "SCHEMA_ERROR";

export class BlastRadiusError extends Error {
  readonly code: ErrorCode;
  readonly detail: string | undefined;

  constructor(code: ErrorCode, message: string, detail?: string) {
    super(message);
    this.name = "BlastRadiusError";
    this.code = code;
    this.detail = detail;
  }

  static binaryNotFound(bin: string): BlastRadiusError {
    return new BlastRadiusError(
      "BINARY_NOT_FOUND",
      `\`${bin}\` was not found on PATH. Install entire-graph or pass --fixture <dir>.`,
    );
  }

  static graph(message: string, detail?: string): BlastRadiusError {
    return new BlastRadiusError("GRAPH_ERROR", message, detail);
  }

  static git(message: string, detail?: string): BlastRadiusError {
    return new BlastRadiusError("GIT_ERROR", message, detail);
  }

  static intentUnavailable(message: string): BlastRadiusError {
    return new BlastRadiusError("INTENT_UNAVAILABLE", message);
  }

  static sink(message: string, detail?: string): BlastRadiusError {
    return new BlastRadiusError("SINK_ERROR", message, detail);
  }

  static config(message: string): BlastRadiusError {
    return new BlastRadiusError("CONFIG_ERROR", message);
  }

  static schema(message: string, detail?: string): BlastRadiusError {
    return new BlastRadiusError("SCHEMA_ERROR", message, detail);
  }
}

/* --------------------------------------------------------------- Result --- */

export type Ok<T> = { readonly ok: true; readonly value: T };
export type Err<E> = { readonly ok: false; readonly error: E };
export type Result<T, E = BlastRadiusError> = Ok<T> | Err<E>;

export const ok = <T>(value: T): Ok<T> => ({ ok: true, value });
export const err = <E>(error: E): Err<E> => ({ ok: false, error });

export const isOk = <T, E>(r: Result<T, E>): r is Ok<T> => r.ok;
export const isErr = <T, E>(r: Result<T, E>): r is Err<E> => !r.ok;

export function map<T, U, E>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  return r.ok ? ok(fn(r.value)) : r;
}

export function mapErr<T, E, F>(r: Result<T, E>, fn: (error: E) => F): Result<T, F> {
  return r.ok ? r : err(fn(r.error));
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

/** Collect an array of Results into a Result of an array (first error wins). */
export function all<T, E>(results: readonly Result<T, E>[]): Result<T[], E> {
  const out: T[] = [];
  for (const r of results) {
    if (!r.ok) return r;
    out.push(r.value);
  }
  return ok(out);
}

/** Partition results, keeping every success and every failure. */
export function settle<T, E>(
  results: readonly Result<T, E>[],
): { values: T[]; errors: E[] } {
  const values: T[] = [];
  const errors: E[] = [];
  for (const r of results) {
    if (r.ok) values.push(r.value);
    else errors.push(r.error);
  }
  return { values, errors };
}

/**
 * Domain value objects — the vocabulary every stage speaks.
 *
 * Raw `entire-graph` JSON is parsed (in `adapters/graph`) into these normalized
 * shapes and nothing downstream ever sees the wire format again. Intermediate
 * types are plain interfaces; the two shapes that cross an outer boundary — the
 * final `AnalysisReport` (rendered / emitted as JSON) and `IntentModel` (may be
 * supplied via config) — also get a zod schema so the contract is enforced.
 */
import { z } from "zod";

export const SCHEMA_VERSION = "1.0.0" as const;

/* ------------------------------------------------------------- symbols --- */

export interface SymbolRef {
  readonly name: string;
  readonly qualifiedName: string;
  readonly kind: string | undefined;
  readonly file: string | undefined;
  readonly line: number | undefined;
  readonly language: string | undefined;
  readonly external: boolean;
}

export type ChangeType =
  | "added"
  | "removed"
  | "renamed"
  | "moved"
  | "signature_changed"
  | "body_changed"
  | "unknown";

export interface ChangedSymbol {
  readonly ref: SymbolRef;
  readonly changeType: ChangeType;
  readonly dependentsCount: number;
  readonly oldSignature: string | undefined;
  readonly newSignature: string | undefined;
}

export interface ChangeSet {
  readonly base: string;
  readonly head: string;
  /** `Entire-Checkpoint` id when the diff resolved one; else undefined. */
  readonly checkpoint: string | undefined;
  readonly symbols: readonly ChangedSymbol[];
  readonly changedFiles: readonly string[];
}

/* --------------------------------------------------------- blast radius --- */

export type RadiusRelation =
  | "CALLS"
  | "CALLED_BY"
  | "USES_TYPE"
  | "PARAM_TYPE"
  | "RETURNS_TYPE"
  | "DATA_FLOWS"
  | "FILE_CHANGES_WITH"
  | "SIBLING"
  | "HANDLES_ROUTE"
  | "OTHER";

export type RadiusSection =
  | "callers"
  | "callees"
  | "type_consumers"
  | "data_flows"
  | "co_changes"
  | "siblings";

export interface RadiusNode {
  readonly ref: SymbolRef;
  readonly section: RadiusSection;
  readonly relation: RadiusRelation;
  readonly direction: "in" | "out" | "none";
  /** graph hops from the nearest changed symbol (1 = direct). */
  readonly distance: number;
  /** intermediate symbol names on the path from the changed symbol. */
  readonly viaChain: readonly string[];
  readonly callSite: { file: string; line: number } | undefined;
  /** qualified names of the changed symbols this node derives from. */
  readonly originSymbols: readonly string[];
  readonly isTest: boolean;
}

export interface BlastRadius {
  readonly origin: readonly ChangedSymbol[];
  readonly nodes: readonly RadiusNode[];
  readonly sectionTotals: Readonly<Record<RadiusSection, number>>;
}

/* --------------------------------------------------------------- intent --- */

export const intentModelSchema = z.object({
  source: z.string(),
  title: z.string().default(""),
  body: z.string().default(""),
  keywords: z.array(z.string()).default([]),
  references: z.array(z.string()).default([]),
});
export type IntentModel = z.infer<typeof intentModelSchema>;

/* ------------------------------------------------------------- findings --- */

export type Severity = "high" | "medium" | "low";

export interface EvidenceItem {
  readonly label: string;
  /** `path/to/file.ts:42` — clickable in a PR comment. */
  readonly location: string | undefined;
  /** e.g. ["Database.query", "LinkRepo.byId", "RedirectService.handle"]. */
  readonly relationPath: readonly string[];
}

export interface Finding {
  readonly symbol: SymbolRef;
  readonly severity: Severity;
  /** which strategy raised it: "keyword-overlap" | "dependents-threshold" | … */
  readonly strategy: string;
  readonly reason: string;
  readonly dependentsCount: number;
  readonly evidence: readonly EvidenceItem[];
}

/* --------------------------------------------------------- test selection --- */

export type TestFramework = "go" | "vitest" | "jest" | "pytest" | "unknown";

export interface TestCandidate {
  readonly ref: SymbolRef;
  readonly score: number;
  readonly distance: number;
  /** qualified names of changed symbols this test transitively reaches. */
  readonly coversSymbols: readonly string[];
  readonly framework: TestFramework;
}

export interface TestPlan {
  readonly framework: TestFramework;
  readonly selected: readonly TestCandidate[];
  /** copy-paste command that runs exactly `selected`, or null if unknown. */
  readonly command: string | null;
  /** qualified names of changed symbols with no covering test. */
  readonly coverageGaps: readonly string[];
}

/* -------------------------------------------------------------- summary --- */

export interface RadiusSummary {
  readonly totalNodes: number;
  readonly fileCount: number;
  readonly moduleCount: number;
  readonly serviceCount: number;
  readonly testCount: number;
  readonly byRelation: Readonly<Record<string, number>>;
}

/* --------------------------------------------------------------- report --- */

export const analysisReportSchema = z.object({
  schemaVersion: z.literal(SCHEMA_VERSION),
  generatedAt: z.string(),
  range: z.object({ base: z.string(), head: z.string(), checkpoint: z.string().optional() }),
  intent: intentModelSchema.nullable(),
  changeSummary: z.object({
    symbolCount: z.number().int(),
    fileCount: z.number().int(),
    widestDependents: z.number().int(),
  }),
  radiusSummary: z.object({
    totalNodes: z.number().int(),
    fileCount: z.number().int(),
    moduleCount: z.number().int(),
    serviceCount: z.number().int(),
    testCount: z.number().int(),
    byRelation: z.record(z.number().int()),
  }),
  findings: z.array(
    z.object({
      symbol: z.object({
        name: z.string(),
        qualifiedName: z.string(),
        kind: z.string().optional(),
        file: z.string().optional(),
        line: z.number().int().optional(),
        language: z.string().optional(),
        external: z.boolean(),
      }),
      severity: z.enum(["high", "medium", "low"]),
      strategy: z.string(),
      reason: z.string(),
      dependentsCount: z.number().int(),
      evidence: z.array(
        z.object({
          label: z.string(),
          location: z.string().optional(),
          relationPath: z.array(z.string()),
        }),
      ),
    }),
  ),
  testPlan: z.object({
    framework: z.enum(["go", "vitest", "jest", "pytest", "unknown"]),
    selected: z.array(
      z.object({
        ref: z.object({
          name: z.string(),
          qualifiedName: z.string(),
          kind: z.string().optional(),
          file: z.string().optional(),
          line: z.number().int().optional(),
          language: z.string().optional(),
          external: z.boolean(),
        }),
        score: z.number(),
        distance: z.number().int(),
        coversSymbols: z.array(z.string()),
        framework: z.enum(["go", "vitest", "jest", "pytest", "unknown"]),
      }),
    ),
    command: z.string().nullable(),
    coverageGaps: z.array(z.string()),
  }),
});

export type AnalysisReport = z.infer<typeof analysisReportSchema>;

/* --------------------------------------------------------------- helpers --- */

export function symbolKey(ref: Pick<SymbolRef, "qualifiedName" | "file">): string {
  return `${ref.file ?? "?"}::${ref.qualifiedName}`;
}

export function formatLocation(ref: Pick<SymbolRef, "file" | "line">): string | undefined {
  if (!ref.file) return undefined;
  return ref.line ? `${ref.file}:${ref.line}` : ref.file;
}

/**
 * A minimal railway-oriented pipeline.
 *
 * A `Stage` maps one value to a `Result` of the next. `chain` threads a value
 * through a list of stages, stopping at the first `Err`. Stages may be sync or
 * async. The `review` use-case composes the real analysis from these; keeping
 * the combinator tiny (rather than a general DAG engine) is deliberate — the
 * fan-out after the blast-radius step is spelled out explicitly in the use-case
 * where it is easy to read.
 */
import type { Result } from "./errors.js";
import { ok } from "./errors.js";

export type Stage<In, Out> = (input: In) => Result<Out> | Promise<Result<Out>>;

/** Run `stages` left to right, feeding each output into the next. */
export async function chain<A, B>(input: A, s1: Stage<A, B>): Promise<Result<B>>;
export async function chain<A, B, C>(
  input: A,
  s1: Stage<A, B>,
  s2: Stage<B, C>,
): Promise<Result<C>>;
export async function chain<A, B, C, D>(
  input: A,
  s1: Stage<A, B>,
  s2: Stage<B, C>,
  s3: Stage<C, D>,
): Promise<Result<D>>;
export async function chain(
  input: unknown,
  ...stages: Stage<unknown, unknown>[]
): Promise<Result<unknown>> {
  let current: Result<unknown> = ok(input);
  for (const stage of stages) {
    if (!current.ok) return current;
    current = await stage(current.value);
  }
  return current;
}

/**
 * Run independent pure computations over the same input and hand every result
 * to `combine`. Used for the scope-check / test-selection / summary fan-out,
 * which never fail (they are pure) so they return plain values, not Results.
 */
export function fanOut<In, A, B, C, Out>(
  input: In,
  branches: readonly [(i: In) => A, (i: In) => B, (i: In) => C],
  combine: (a: A, b: B, c: C) => Out,
): Out {
  const [fa, fb, fc] = branches;
  return combine(fa(input), fb(input), fc(input));
}

import { describe, expect, it } from "vitest";
import {
  all,
  BlastRadiusError,
  err,
  isErr,
  isOk,
  map,
  mapErr,
  ok,
  settle,
  unwrapOr,
} from "../../src/domain/errors.js";

describe("Result", () => {
  it("ok / err construct and narrow", () => {
    expect(isOk(ok(1))).toBe(true);
    expect(isErr(err("x"))).toBe(true);
  });

  it("map only transforms the ok branch", () => {
    expect(map(ok(2), (n) => n * 3)).toEqual(ok(6));
    const e = err(new BlastRadiusError("GIT_ERROR", "boom"));
    expect(map(e, (n: number) => n * 3)).toBe(e);
  });

  it("mapErr only transforms the err branch", () => {
    expect(mapErr(ok(2), () => "nope")).toEqual(ok(2));
    expect(mapErr(err("a"), (s) => s + "b")).toEqual(err("ab"));
  });

  it("unwrapOr returns the fallback on err", () => {
    expect(unwrapOr(ok(5), 0)).toBe(5);
    expect(unwrapOr(err("e"), 0)).toBe(0);
  });

  it("all short-circuits on the first err", () => {
    expect(all([ok(1), ok(2), ok(3)])).toEqual(ok([1, 2, 3]));
    expect(all([ok(1), err("bad"), ok(3)])).toEqual(err("bad"));
  });

  it("settle keeps every value and every error", () => {
    expect(settle([ok(1), err("a"), ok(2), err("b")])).toEqual({
      values: [1, 2],
      errors: ["a", "b"],
    });
  });
});

describe("BlastRadiusError", () => {
  it("factory helpers set the code", () => {
    expect(BlastRadiusError.binaryNotFound("entire-graph").code).toBe("BINARY_NOT_FOUND");
    expect(BlastRadiusError.graph("x").code).toBe("GRAPH_ERROR");
    expect(BlastRadiusError.git("x").code).toBe("GIT_ERROR");
    expect(BlastRadiusError.intentUnavailable("x").code).toBe("INTENT_UNAVAILABLE");
    expect(BlastRadiusError.sink("x").code).toBe("SINK_ERROR");
    expect(BlastRadiusError.config("x").code).toBe("CONFIG_ERROR");
  });

  it("carries an optional detail", () => {
    expect(BlastRadiusError.graph("msg", "stderr line").detail).toBe("stderr line");
  });
});

import { describe, expect, it } from "vitest";
import { err, ok } from "../../src/domain/errors.js";
import { chain, fanOut } from "../../src/domain/pipeline.js";

describe("chain", () => {
  it("threads a value through sync and async stages", async () => {
    const r = await chain(
      2,
      (n: number) => ok(n + 1),
      async (n: number) => ok(n * 10),
    );
    expect(r).toEqual(ok(30));
  });

  it("stops at the first err and skips later stages", async () => {
    let reached = false;
    const r = await chain(
      1,
      () => err("stop"),
      (n: number) => {
        reached = true;
        return ok(n);
      },
    );
    expect(r).toEqual(err("stop"));
    expect(reached).toBe(false);
  });
});

describe("fanOut", () => {
  it("runs every branch on the same input and combines", () => {
    const out = fanOut(
      10,
      [(n) => n + 1, (n) => n * 2, (n) => `${n}`],
      (a, b, c) => ({ a, b, c }),
    );
    expect(out).toEqual({ a: 11, b: 20, c: "10" });
  });
});

