/**
 * Is this symbol a test? Pure, shared by the radius tagger and test selection.
 *
 * Two signals: the file path matches a test glob, or the symbol name matches a
 * framework's test-name convention. Globs are configurable so a curveball
 * ("this repo puts tests in `spec/`") is a config change, not a code change.
 */
import type { SymbolRef, TestFramework } from "./model.js";

export const DEFAULT_TEST_FILE_PATTERNS: readonly RegExp[] = [
  /(^|\/)__tests__\//,
  /(^|\/)tests?\//,
  /(^|\/)spec\//,
  /\.test\.[cm]?[jt]sx?$/,
  /\.spec\.[cm]?[jt]sx?$/,
  /_test\.go$/,
  /(^|\/)test_[^/]+\.py$/,
  /_test\.py$/,
  /Test\.java$/,
  /Tests?\.(cs|kt|swift)$/,
  /_spec\.rb$/,
];

const TEST_NAME_PATTERNS: readonly RegExp[] = [
  /^Test[A-Z_]/, // Go
  /^test_/, // pytest / unittest
  /_test$/,
  /^(it|describe|test)\b/i, // vitest/jest blocks occasionally surface as symbols
];

export interface TestDetectOptions {
  readonly filePatterns?: readonly RegExp[];
}

export function isTestFile(file: string | undefined, opts: TestDetectOptions = {}): boolean {
  if (!file) return false;
  const patterns = opts.filePatterns ?? DEFAULT_TEST_FILE_PATTERNS;
  const normalized = file.replace(/\\/g, "/");
  return patterns.some((re) => re.test(normalized));
}

export function isTestSymbol(ref: SymbolRef, opts: TestDetectOptions = {}): boolean {
  if (isTestFile(ref.file, opts)) return true;
  return TEST_NAME_PATTERNS.some((re) => re.test(ref.name));
}

/** Best-effort framework guess from a test file path + language. */
export function frameworkOf(ref: SymbolRef): TestFramework {
  const file = (ref.file ?? "").replace(/\\/g, "/");
  const lang = (ref.language ?? "").toLowerCase();
  if (file.endsWith("_test.go") || lang === "go") return "go";
  if (/\.(test|spec)\.[cm]?[jt]sx?$/.test(file)) {
    // vitest and jest share the file convention; default to vitest, the use-case
    // can override from config / a detected dependency.
    return "vitest";
  }
  if (/(^|\/)test_.*\.py$/.test(file) || /_test\.py$/.test(file) || lang === "python") {
    return "pytest";
  }
  return "unknown";
}

/**
 * Pure mappers: validated raw `entire-graph` JSON  ->  domain value objects.
 *
 * The graph adapters do the I/O and the zod parse, then call these. Keeping the
 * translation here (not in the adapter) means it is covered by fast unit tests
 * with plain fixtures and there is exactly one place that knows the wire shape.
 */
import type {
  RawDiffResult,
  RawEndpoint,
  RawImpactEntry,
  RawImpactResult,
} from "./graph-schema.js";
import { IMPACT_SECTIONS, type ImpactSectionName } from "./graph-schema.js";
import type {
  ChangedSymbol,
  ChangeSet,
  ChangeType,
  RadiusNode,
  RadiusRelation,
  RadiusSection,
  SymbolRef,
} from "./model.js";
import { isTestSymbol } from "./test-detect.js";

/* --------------------------------------------------------------- symbols --- */

export function toSymbolRef(ep: RawEndpoint): SymbolRef {
  const qualified = ep.qualified_name && ep.qualified_name.length > 0 ? ep.qualified_name : ep.name;
  return {
    name: ep.name,
    qualifiedName: qualified,
    kind: ep.kind,
    file: ep.file_path,
    line: ep.start_line,
    language: ep.language,
    external: ep.external ?? false,
  };
}

const CHANGE_TYPE_MAP: Record<string, ChangeType> = {
  added: "added",
  removed: "removed",
  renamed: "renamed",
  moved: "moved",
  signature_changed: "signature_changed",
  body_changed: "body_changed",
};

function mapChangeType(raw: string, reconciliation: string | undefined): ChangeType {
  if (reconciliation === "MOVED") return "moved";
  if (reconciliation === "RENAMED") return "renamed";
  return CHANGE_TYPE_MAP[raw] ?? "unknown";
}

/* ----------------------------------------------------------------- diff --- */

/** Structural (module-scope) change rows we don't treat as symbols. */
const NON_SYMBOL_KINDS = new Set(["module", "file"]);

export function toChangeSet(raw: RawDiffResult): ChangeSet {
  const symbols: ChangedSymbol[] = [];
  const changedFiles = new Set<string>();

  for (const file of raw.files) {
    changedFiles.add(file.path);
    for (const change of file.changes) {
      if (NON_SYMBOL_KINDS.has(change.kind)) continue;
      const line = change.after_start_line ?? change.before_start_line;
      const ref: SymbolRef = {
        name: change.new_name ?? change.name,
        qualifiedName: change.new_name ?? change.name,
        kind: change.kind,
        file: change.new_path ?? file.path,
        line: line && line > 0 ? line : undefined,
        language: file.language,
        external: false,
      };
      symbols.push({
        ref,
        changeType: mapChangeType(change.type, change.reconciliation),
        dependentsCount: change.dependents_count,
        oldSignature: change.old_signature,
        newSignature: change.new_signature,
      });
    }
  }

  return {
    base: raw.base,
    head: raw.head,
    checkpoint: raw.checkpoint,
    symbols,
    changedFiles: [...changedFiles],
  };
}

/* --------------------------------------------------------------- impact --- */

const SECTION_TO_RELATION: Record<ImpactSectionName, RadiusRelation> = {
  callers: "CALLED_BY",
  callees: "CALLS",
  type_consumers: "USES_TYPE",
  data_flows: "DATA_FLOWS",
  co_changes: "FILE_CHANGES_WITH",
  siblings: "SIBLING",
};

const SECTION_TO_DOMAIN: Record<ImpactSectionName, RadiusSection> = {
  callers: "callers",
  callees: "callees",
  type_consumers: "type_consumers",
  data_flows: "data_flows",
  co_changes: "co_changes",
  siblings: "siblings",
};

function relationOf(section: ImpactSectionName, entry: RawImpactEntry): RadiusRelation {
  const explicit = entry.relation?.toUpperCase();
  if (explicit === "USES_TYPE" || explicit === "PARAM_TYPE" || explicit === "RETURNS_TYPE") {
    return explicit;
  }
  return SECTION_TO_RELATION[section];
}

function directionOf(entry: RawImpactEntry): "in" | "out" | "none" {
  return entry.direction === "in" || entry.direction === "out" ? entry.direction : "none";
}

/**
 * One impact result -> the radius nodes it contributes, all tagged with the
 * changed symbol they came from.
 */
export function toRadiusNodes(raw: RawImpactResult, originQualifiedName: string): RadiusNode[] {
  const nodes: RadiusNode[] = [];

  for (const section of IMPACT_SECTIONS) {
    const bucket = raw[section];
    for (const entry of bucket.entries) {
      const ref = toSymbolRef(entry.endpoint);
      const via = entry.via ? entry.via.split(/\s*->\s*|\s*,\s*/).filter(Boolean) : [];
      nodes.push({
        ref,
        section: SECTION_TO_DOMAIN[section],
        relation: relationOf(section, entry),
        direction: directionOf(entry),
        distance: entry.depth && entry.depth > 0 ? entry.depth : 1,
        viaChain: via,
        callSite: entry.call_site
          ? { file: entry.call_site.file_path, line: entry.call_site.line }
          : undefined,
        originSymbols: [originQualifiedName],
        isTest: isTestSymbol(ref),
      });
    }
  }

  return nodes;
}

export function isDisambiguationRequired(raw: RawImpactResult): boolean {
  return raw.disambiguation_required === true;
}

/**
 * Fold the per-changed-symbol impact node lists into one blast radius.
 *
 * Rules:
 *  - dedupe by (file, qualifiedName): the same downstream symbol reached from
 *    two changed symbols is one node, keeping the SHORTEST distance and the
 *    union of origin symbols;
 *  - a node that is itself one of the changed symbols is dropped (it is the
 *    origin, not the blast);
 *  - section totals count distinct nodes per section after dedupe.
 */
import type { BlastRadius, ChangedSymbol, RadiusNode, RadiusSection } from "./model.js";
import { symbolKey } from "./model.js";

const SECTIONS: readonly RadiusSection[] = [
  "callers",
  "callees",
  "type_consumers",
  "data_flows",
  "co_changes",
  "siblings",
];

function emptyTotals(): Record<RadiusSection, number> {
  return { callers: 0, callees: 0, type_consumers: 0, data_flows: 0, co_changes: 0, siblings: 0 };
}

function mergeNode(existing: RadiusNode, incoming: RadiusNode): RadiusNode {
  const origins = new Set([...existing.originSymbols, ...incoming.originSymbols]);
  const closer = incoming.distance < existing.distance ? incoming : existing;
  return {
    ...closer,
    originSymbols: [...origins],
    // keep the richer via chain / call site if the closer one lacks it
    viaChain: closer.viaChain.length > 0 ? closer.viaChain : existing.viaChain,
    callSite: closer.callSite ?? existing.callSite,
    isTest: existing.isTest || incoming.isTest,
  };
}

export function computeBlastRadius(
  origin: readonly ChangedSymbol[],
  nodeLists: readonly (readonly RadiusNode[])[],
): BlastRadius {
  const originKeys = new Set(origin.map((s) => symbolKey(s.ref)));
  const byKey = new Map<string, RadiusNode>();

  for (const list of nodeLists) {
    for (const node of list) {
      if (node.ref.external) {
        // external callees (fmt.Errorf, etc.) are noise for a review summary
        if (node.section === "callees") continue;
      }
      const key = symbolKey(node.ref);
      if (originKeys.has(key)) continue;
      const existing = byKey.get(key);
      byKey.set(key, existing ? mergeNode(existing, node) : node);
    }
  }

  const nodes = [...byKey.values()].sort(
    (a, b) => a.distance - b.distance || a.ref.qualifiedName.localeCompare(b.ref.qualifiedName),
  );

  const sectionTotals = emptyTotals();
  for (const node of nodes) sectionTotals[node.section] += 1;

  return { origin: [...origin], nodes, sectionTotals };
}

/** Nodes that sit on a caller path (what a reviewer most wants to see). */
export function upstreamNodes(radius: BlastRadius): RadiusNode[] {
  return radius.nodes.filter((n) => n.section === "callers");
}

export { SECTIONS as RADIUS_SECTIONS };

/**
 * Headline metrics for the report: how wide is this change, really.
 */
import type { BlastRadius, RadiusSummary } from "./model.js";

export interface SummaryOptions {
  /** how many leading path segments define a "module" (default 2). */
  readonly moduleDepth?: number;
  /** relations that mark a service boundary. */
  readonly serviceRelations?: readonly string[];
}

const DEFAULT_SERVICE_RELATIONS = ["HANDLES_ROUTE", "HTTP_CALLS", "EMITS", "LISTENS_ON"];

function moduleOf(file: string, depth: number): string {
  const parts = file.replace(/\\/g, "/").split("/");
  if (parts.length <= 1) return parts[0] ?? file;
  return parts.slice(0, depth).join("/");
}

export function summarizeRadius(radius: BlastRadius, opts: SummaryOptions = {}): RadiusSummary {
  const moduleDepth = opts.moduleDepth ?? 2;
  const serviceRelations = new Set(opts.serviceRelations ?? DEFAULT_SERVICE_RELATIONS);

  const files = new Set<string>();
  const modules = new Set<string>();
  const services = new Set<string>();
  const byRelation: Record<string, number> = {};
  let testCount = 0;

  for (const node of radius.nodes) {
    if (node.ref.file) {
      files.add(node.ref.file);
      modules.add(moduleOf(node.ref.file, moduleDepth));
    }
    byRelation[node.relation] = (byRelation[node.relation] ?? 0) + 1;
    if (serviceRelations.has(node.relation) && node.ref.file) {
      services.add(moduleOf(node.ref.file, moduleDepth));
    }
    if (node.isTest) testCount += 1;
  }

  return {
    totalNodes: radius.nodes.length,
    fileCount: files.size,
    moduleCount: modules.size,
    serviceCount: services.size,
    testCount,
    byRelation,
  };
}

