/**
 * Turn free-text intent (a PR body, an issue, a checkpoint prompt) into a set
 * of comparable keywords, and split a symbol's identity into comparable tokens.
 *
 * Deliberately simple and inspectable — no embeddings. The scope-creep check
 * has to be explainable to a reviewer in one sentence ("this symbol shares no
 * words with the ticket"), and a lexical overlap is exactly that sentence.
 */

const STOPWORDS = new Set([
  "a", "an", "the", "and", "or", "but", "if", "then", "else", "for", "of", "to", "in", "on",
  "at", "by", "with", "from", "as", "is", "are", "be", "been", "being", "was", "were", "this",
  "that", "these", "those", "it", "its", "we", "i", "you", "they", "should", "would", "could",
  "can", "will", "shall", "may", "might", "must", "add", "adds", "added", "adding", "update",
  "updates", "updated", "fix", "fixes", "fixed", "change", "changes", "changed", "make", "makes",
  "made", "use", "using", "used", "support", "implement", "implements", "new", "also", "when",
  "so", "not", "no", "yes", "do", "does", "did", "done", "now", "just", "only", "into", "out",
  "up", "down", "via", "per", "each", "any", "all", "some", "more", "less", "than", "there",
  "here", "which", "what", "who", "how", "why", "pr", "issue", "ticket", "feature", "bug",
]);

/** camelCase / snake_case / kebab / dotted / slashed -> lowercase word list. */
export function splitIdentifier(raw: string): string[] {
  return raw
    .replace(/[/\\.]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
}

/** Naive suffix stemmer — enough to make "limiter"/"limiting"/"limits" collide. */
export function stem(word: string): string {
  return word
    .replace(/(ies)$/, "y")
    .replace(/(ing|edly|ed|ly|es|s)$/, "")
    .replace(/(er|or)$/, "");
}

function normalize(words: Iterable<string>): Set<string> {
  const out = new Set<string>();
  for (const w of words) {
    if (w.length < 3) continue;
    if (STOPWORDS.has(w)) continue;
    const s = stem(w);
    if (s.length >= 3 && !STOPWORDS.has(s)) out.add(s);
  }
  return out;
}

/** Keywords for an intent text. `backtickedTerms` are weighted in as-is. */
export function extractKeywords(text: string): string[] {
  // pull `code spans` and Capitalised identifiers before generic splitting
  const spans = [...text.matchAll(/`([^`]+)`/g)].flatMap((m) => splitIdentifier(m[1] ?? ""));
  const words = splitIdentifier(text.replace(/`[^`]+`/g, " "));
  return [...normalize([...spans, ...words])].sort();
}

/** Tokens that identify a symbol: its qualified name + the meaningful path parts. */
export function symbolTokens(qualifiedName: string, file: string | undefined): Set<string> {
  const fromName = splitIdentifier(qualifiedName);
  const fromFile = file
    ? splitIdentifier(file.replace(/\.[a-z0-9]+$/i, "")).filter(
        (p) => !["src", "internal", "pkg", "lib", "app", "cmd", "test", "tests"].includes(p),
      )
    : [];
  return normalize([...fromName, ...fromFile]);
}

export interface OverlapResult {
  readonly overlap: number;
  readonly shared: string[];
  readonly symbolTokenCount: number;
}

/** Fraction of a symbol's tokens that appear in the intent keyword set. */
export function keywordOverlap(
  qualifiedName: string,
  file: string | undefined,
  intentKeywords: readonly string[],
): OverlapResult {
  const tokens = symbolTokens(qualifiedName, file);
  if (tokens.size === 0) return { overlap: 1, shared: [], symbolTokenCount: 0 };
  const kw = new Set(intentKeywords);
  const shared = [...tokens].filter((t) => kw.has(t));
  return { overlap: shared.length / tokens.size, shared, symbolTokenCount: tokens.size };
}

/**
 * Scope-creep detection as a set of interchangeable strategies.
 *
 * A strategy looks at the changed symbols (and, for evidence, the blast radius)
 * and raises `Finding`s for changes that look like they drifted from the stated
 * intent. `CompositeStrategy` runs several and merges their findings. Adding or
 * swapping a heuristic — a very plausible Noon Curve Ball — touches only this
 * folder.
 */
import type { BlastRadius, ChangeSet, Finding, IntentModel, Severity, SymbolRef } from "../model.js";
import { formatLocation, symbolKey } from "../model.js";

export interface ScopeCreepInput {
  readonly changeSet: ChangeSet;
  readonly intent: IntentModel | null;
  readonly radius: BlastRadius;
}

export interface ScopeCreepStrategy {
  readonly name: string;
  evaluate(input: ScopeCreepInput): Finding[];
}

const SEVERITY_RANK: Record<Severity, number> = { high: 3, medium: 2, low: 1 };

export class CompositeStrategy implements ScopeCreepStrategy {
  readonly name = "composite";
  private readonly strategies: readonly ScopeCreepStrategy[];

  constructor(strategies: readonly ScopeCreepStrategy[]) {
    this.strategies = strategies;
  }

  evaluate(input: ScopeCreepInput): Finding[] {
    const merged = new Map<string, Finding>();

    for (const strategy of this.strategies) {
      for (const finding of strategy.evaluate(input)) {
        const key = symbolKey(finding.symbol);
        const existing = merged.get(key);
        if (!existing) {
          merged.set(key, { ...finding, strategy: finding.strategy });
          continue;
        }
        merged.set(key, {
          ...existing,
          severity:
            SEVERITY_RANK[finding.severity] > SEVERITY_RANK[existing.severity]
              ? finding.severity
              : existing.severity,
          strategy: `${existing.strategy}, ${finding.strategy}`,
          reason: `${existing.reason}; ${finding.reason}`,
          evidence: [...existing.evidence, ...finding.evidence],
        });
      }
    }

    return [...merged.values()].sort(
      (a, b) =>
        SEVERITY_RANK[b.severity] - SEVERITY_RANK[a.severity] ||
        b.dependentsCount - a.dependentsCount,
    );
  }
}

/* ------------------------------------------------------- shared helpers --- */

/** Nearest caller-path symbols for a changed symbol — the "who is affected" trail. */
export function callerTrail(
  radius: BlastRadius,
  changedQualifiedName: string,
  limit = 3,
): { path: string[]; locations: { label: string; location: string | undefined }[] } {
  const related = radius.nodes
    .filter(
      (n) =>
        n.section === "callers" &&
        n.originSymbols.includes(changedQualifiedName) &&
        !n.isTest,
    )
    .sort((a, b) => a.distance - b.distance)
    .slice(0, limit);

  return {
    path: [changedQualifiedName, ...related.map((n) => n.ref.qualifiedName)],
    locations: related.map((n) => ({
      label: n.ref.qualifiedName,
      location: formatLocation(n.ref),
    })),
  };
}

export function severityForDependents(count: number): Severity {
  if (count >= 15) return "high";
  if (count >= 6) return "medium";
  return "low";
}

export function refLabel(ref: SymbolRef): string {
  const loc = formatLocation(ref);
  return loc ? `\`${ref.qualifiedName}\` (${loc})` : `\`${ref.qualifiedName}\``;
}

/**
 * "This changed symbol shares no vocabulary with the stated intent, and other
 * code depends on it." — the core scope-creep signal.
 *
 * Needs an intent; with none it stays silent (you cannot judge drift from an
 * ask you do not have).
 */
import { keywordOverlap } from "../intent-keywords.js";
import type { Finding } from "../model.js";
import { formatLocation } from "../model.js";
import {
  callerTrail,
  type ScopeCreepInput,
  type ScopeCreepStrategy,
  severityForDependents,
} from "./strategy.js";

export interface KeywordOverlapOptions {
  /** below this overlap fraction the symbol looks unrelated to the intent. */
  readonly maxOverlap?: number;
  /** and it only matters if at least this many things depend on it. */
  readonly minDependents?: number;
}

export class KeywordOverlapStrategy implements ScopeCreepStrategy {
  readonly name = "keyword-overlap";
  private readonly maxOverlap: number;
  private readonly minDependents: number;

  constructor(opts: KeywordOverlapOptions = {}) {
    this.maxOverlap = opts.maxOverlap ?? 0.15;
    this.minDependents = opts.minDependents ?? 3;
  }

  evaluate(input: ScopeCreepInput): Finding[] {
    const { intent, changeSet, radius } = input;
    if (!intent || intent.keywords.length === 0) return [];

    const findings: Finding[] = [];

    for (const changed of changeSet.symbols) {
      if (changed.changeType === "added") continue; // new code can't "drift"
      if (changed.dependentsCount < this.minDependents) continue;

      const { overlap, shared, symbolTokenCount } = keywordOverlap(
        changed.ref.qualifiedName,
        changed.ref.file,
        intent.keywords,
      );
      if (symbolTokenCount === 0 || overlap > this.maxOverlap) continue;

      const trail = callerTrail(radius, changed.ref.qualifiedName);
      findings.push({
        symbol: changed.ref,
        severity: severityForDependents(changed.dependentsCount),
        strategy: this.name,
        reason:
          shared.length === 0
            ? `no vocabulary overlap with the stated intent`
            : `weak overlap with the stated intent (only: ${shared.join(", ")})`,
        dependentsCount: changed.dependentsCount,
        evidence: [
          {
            label: `intent (${intent.source}): "${intent.title || intent.body.slice(0, 80)}"`,
            location: undefined,
            relationPath: [],
          },
          {
            label: `changed here — ${changed.changeType.replace("_", " ")}, ${changed.dependentsCount} dependents`,
            location: formatLocation(changed.ref),
            relationPath: [],
          },
          ...(trail.locations.length > 0
            ? [
                {
                  label: `reaches ${trail.locations.map((l) => l.label).join(" → ")}`,
                  location: trail.locations[0]?.location,
                  relationPath: trail.path,
                },
              ]
            : []),
        ],
      });
    }

    return findings;
  }
}

/**
 * "This change is wide-reaching." — a lot of code depends on a symbol that was
 * modified, whether or not there is a stated intent. On its own it is not proof
 * of scope creep, but it is always worth the reviewer's eyes, and combined with
 * a keyword-overlap miss it is a strong signal.
 */
import type { Finding } from "../model.js";
import { formatLocation } from "../model.js";
import {
  callerTrail,
  type ScopeCreepInput,
  type ScopeCreepStrategy,
  severityForDependents,
} from "./strategy.js";

export interface DependentsThresholdOptions {
  /** dependents at or above this make the change "wide-reaching". */
  readonly threshold?: number;
}

export class DependentsThresholdStrategy implements ScopeCreepStrategy {
  readonly name = "dependents-threshold";
  private readonly threshold: number;

  constructor(opts: DependentsThresholdOptions = {}) {
    this.threshold = opts.threshold ?? 8;
  }

  evaluate(input: ScopeCreepInput): Finding[] {
    const findings: Finding[] = [];

    for (const changed of input.changeSet.symbols) {
      if (changed.dependentsCount < this.threshold) continue;
      if (changed.changeType === "added") continue;

      const trail = callerTrail(input.radius, changed.ref.qualifiedName);
      const signatureChange =
        changed.changeType === "signature_changed" || changed.changeType === "renamed";

      findings.push({
        symbol: changed.ref,
        severity: severityForDependents(changed.dependentsCount),
        strategy: this.name,
        reason: signatureChange
          ? `${changed.changeType.replace("_", " ")} on a symbol with ${changed.dependentsCount} dependents — run tests first`
          : `wide-reaching change: ${changed.dependentsCount} dependents`,
        dependentsCount: changed.dependentsCount,
        evidence: [
          {
            label: `${changed.changeType.replace("_", " ")}${
              changed.oldSignature && changed.newSignature
                ? `: \`${changed.oldSignature}\` → \`${changed.newSignature}\``
                : ""
            }`,
            location: formatLocation(changed.ref),
            relationPath: [],
          },
          ...(trail.locations.length > 0
            ? [
                {
                  label: `dependents include ${trail.locations.map((l) => l.label).join(", ")}`,
                  location: trail.locations[0]?.location,
                  relationPath: trail.path,
                },
              ]
            : []),
        ],
      });
    }

    return findings;
  }
}

/**
 * Scope-creep detection — public surface.
 */
export type { ScopeCreepStrategy, ScopeCreepInput } from "./strategy.js";
export { CompositeStrategy } from "./strategy.js";
export { KeywordOverlapStrategy } from "./keyword-overlap.js";
export { DependentsThresholdStrategy } from "./dependents.js";

import { DependentsThresholdStrategy } from "./dependents.js";
import { KeywordOverlapStrategy } from "./keyword-overlap.js";
import { CompositeStrategy, type ScopeCreepStrategy } from "./strategy.js";

export interface ScopeCreepConfig {
  readonly keywordMaxOverlap?: number;
  readonly keywordMinDependents?: number;
  readonly dependentsThreshold?: number;
}

/** The default detector: keyword-overlap + wide-reaching-change, merged. */
export function defaultScopeCreepStrategy(cfg: ScopeCreepConfig = {}): ScopeCreepStrategy {
  return new CompositeStrategy([
    new KeywordOverlapStrategy({
      ...(cfg.keywordMaxOverlap !== undefined ? { maxOverlap: cfg.keywordMaxOverlap } : {}),
      ...(cfg.keywordMinDependents !== undefined
        ? { minDependents: cfg.keywordMinDependents }
        : {}),
    }),
    new DependentsThresholdStrategy(
      cfg.dependentsThreshold !== undefined ? { threshold: cfg.dependentsThreshold } : {},
    ),
  ]);
}

