/**
 * GraphProvider port — everything Blast Radius needs from Entire Graph.
 *
 * Implementations return already-validated domain value objects; the raw wire
 * format never escapes the adapter. Two implementations ship:
 *   - EntireGraphCliAdapter  (shells out to the real `entire-graph` binary)
 *   - FixtureGraphAdapter     (reads recorded JSON — dev, tests, offline demo)
 */
import type { Result } from "../domain/errors.js";
import type { ChangeSet, RadiusNode, SymbolRef } from "../domain/model.js";

export interface CommitRange {
  readonly base: string;
  readonly head: string;
}

export interface ImpactQuery {
  readonly name: string;
  readonly file: string | undefined;
  readonly line: number | undefined;
}

export interface ImpactResult {
  /** blast-radius nodes contributed by this one symbol, origin already tagged. */
  readonly nodes: readonly RadiusNode[];
  /** the graph could not resolve the name to a single definition. */
  readonly disambiguationRequired: boolean;
}

export interface GraphProvider {
  readonly kind: string;
  diff(range: CommitRange): Promise<Result<ChangeSet>>;
  impact(query: ImpactQuery): Promise<Result<ImpactResult>>;
}

export function impactQueryFor(sym: SymbolRef): ImpactQuery {
  return { name: sym.qualifiedName, file: sym.file, line: sym.line };
}

/**
 * FixtureGraphAdapter — serves recorded `entire-graph` JSON from a directory.
 *
 * Layout (either form works):
 *   <dir>/scenario.json         { "diff": "...", "impacts": { "<qname>": "..." } }
 *   <dir>/diff.json             + <dir>/impact-<qname>.json   (convention)
 *
 * This is what makes the whole pipeline runnable with only Node — every test
 * and the offline demo go through here.
 */
import { readFile } from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import { BlastRadiusError, err, ok, type Result } from "../../domain/errors.js";
import { toChangeSet, toRadiusNodes } from "../../domain/graph-mapping.js";
import { rawDiffResult, rawImpactResult } from "../../domain/graph-schema.js";
import type { ChangeSet } from "../../domain/model.js";
import type {
  CommitRange,
  GraphProvider,
  ImpactQuery,
  ImpactResult,
} from "../../ports/graph-provider.js";

const scenarioSchema = z.object({
  diff: z.string(),
  impacts: z.record(z.string()).default({}),
});

function sanitize(name: string): string {
  return name.replace(/[^A-Za-z0-9._-]+/g, "_");
}

export class FixtureGraphAdapter implements GraphProvider {
  readonly kind = "fixture";
  private readonly dir: string;
  private manifest: z.infer<typeof scenarioSchema> | null = null;
  private manifestLoaded = false;

  constructor(dir: string) {
    this.dir = dir;
  }

  private async readJson(file: string): Promise<Result<unknown>> {
    try {
      const raw = await readFile(path.resolve(this.dir, file), "utf8");
      return ok(JSON.parse(raw));
    } catch (e) {
      return err(
        BlastRadiusError.graph(`fixture not found or invalid: ${file}`, (e as Error).message),
      );
    }
  }

  private async loadManifest(): Promise<void> {
    if (this.manifestLoaded) return;
    this.manifestLoaded = true;
    const res = await this.readJson("scenario.json");
    if (res.ok) {
      const parsed = scenarioSchema.safeParse(res.value);
      if (parsed.success) this.manifest = parsed.data;
    }
  }

  async diff(_range: CommitRange): Promise<Result<ChangeSet>> {
    await this.loadManifest();
    const file = this.manifest?.diff ?? "diff.json";
    const res = await this.readJson(file);
    if (!res.ok) return res;
    const parsed = rawDiffResult.safeParse(res.value);
    if (!parsed.success) {
      return err(BlastRadiusError.schema("fixture diff failed schema", parsed.error.message));
    }
    return ok(toChangeSet(parsed.data));
  }

  async impact(query: ImpactQuery): Promise<Result<ImpactResult>> {
    await this.loadManifest();
    const candidates = [
      this.manifest?.impacts[query.name],
      `impact-${sanitize(query.name)}.json`,
      `impact-${sanitize(query.name.split(".").pop() ?? query.name)}.json`,
      path.join("impact", `${sanitize(query.name)}.json`),
    ].filter((c): c is string => !!c);

    for (const file of candidates) {
      const res = await this.readJson(file);
      if (!res.ok) continue;
      const parsed = rawImpactResult.safeParse(res.value);
      if (!parsed.success) {
        return err(BlastRadiusError.schema(`fixture ${file} failed schema`, parsed.error.message));
      }
      return ok({
        nodes: toRadiusNodes(parsed.data, query.name),
        disambiguationRequired: parsed.data.disambiguation_required,
      });
    }

    // a symbol with no recorded impact simply contributes nothing
    return ok({ nodes: [], disambiguationRequired: false });
  }
}

/**
 * EntireGraphCliAdapter — the real thing. Shells out to `entire-graph`.
 *
 * `execa` with an argv array (never a shell string) so a ref or symbol name
 * cannot inject. Non-zero exit and unparseable stdout both become a
 * `BlastRadiusError`, never a throw.
 */
import { execa, type ExecaError } from "execa";
import { BlastRadiusError, err, ok, type Result } from "../../domain/errors.js";
import { toChangeSet, toRadiusNodes } from "../../domain/graph-mapping.js";
import { rawDiffResult, rawImpactResult } from "../../domain/graph-schema.js";
import type { ChangeSet } from "../../domain/model.js";
import type {
  CommitRange,
  GraphProvider,
  ImpactQuery,
  ImpactResult,
} from "../../ports/graph-provider.js";

export interface EntireGraphCliOptions {
  /** binary name or path (default "entire-graph"). */
  readonly binary?: string;
  /** repo path passed as --repo (default "."). */
  readonly repo?: string;
  /** query the committed tree; recommended in CI where head is a commit. */
  readonly head?: boolean;
  /** parsing profile (default "full" for correctness). */
  readonly profile?: "syntax-only" | "fast" | "full";
  /** per-call timeout ms (default 240000 — a cold index build is slow). */
  readonly timeoutMs?: number;
  /** depth for impact (default 2). */
  readonly impactDepth?: 1 | 2;
}

export class EntireGraphCliAdapter implements GraphProvider {
  readonly kind = "entire-graph-cli";
  private readonly binary: string;
  private readonly repo: string;
  private readonly useHead: boolean;
  private readonly profile: "syntax-only" | "fast" | "full";
  private readonly timeoutMs: number;
  private readonly impactDepth: 1 | 2;

  constructor(opts: EntireGraphCliOptions = {}) {
    this.binary = opts.binary ?? "entire-graph";
    this.repo = opts.repo ?? ".";
    this.useHead = opts.head ?? false;
    this.profile = opts.profile ?? "full";
    this.timeoutMs = opts.timeoutMs ?? 240_000;
    this.impactDepth = opts.impactDepth ?? 2;
  }

  private async run(args: string[]): Promise<Result<unknown>> {
    try {
      const { stdout } = await execa(this.binary, args, {
        timeout: this.timeoutMs,
        reject: true,
        stripFinalNewline: true,
      });
      try {
        return ok(JSON.parse(stdout));
      } catch {
        return err(
          BlastRadiusError.graph(
            `\`${this.binary} ${args[0]}\` did not return JSON`,
            stdout.slice(0, 400),
          ),
        );
      }
    } catch (e) {
      const ex = e as ExecaError;
      if (ex.code === "ENOENT") return err(BlastRadiusError.binaryNotFound(this.binary));
      return err(
        BlastRadiusError.graph(
          `\`${this.binary} ${args[0]}\` failed (exit ${ex.exitCode ?? "?"})`,
          (ex.stderr || ex.shortMessage || ex.message)?.slice(0, 400),
        ),
      );
    }
  }

  async diff(range: CommitRange): Promise<Result<ChangeSet>> {
    const res = await this.run([
      "diff",
      "--repo",
      this.repo,
      "--base",
      range.base,
      "--head",
      range.head,
      "--json",
    ]);
    if (!res.ok) return res;
    const parsed = rawDiffResult.safeParse(res.value);
    if (!parsed.success) {
      return err(BlastRadiusError.schema("diff JSON failed schema", parsed.error.message));
    }
    return ok(toChangeSet(parsed.data));
  }

  async impact(query: ImpactQuery): Promise<Result<ImpactResult>> {
    const args = [
      "impact",
      "--repo",
      this.repo,
      "--symbol",
      query.name,
      "--format",
      "json",
      "--depth",
      String(this.impactDepth),
      "--profile",
      this.profile,
    ];
    if (query.file) args.push("--file", query.file);
    if (query.line) args.push("--line", String(query.line));
    if (this.useHead) args.push("--head");

    const res = await this.run(args);
    if (!res.ok) return res;
    const parsed = rawImpactResult.safeParse(res.value);
    if (!parsed.success) {
      return err(BlastRadiusError.schema("impact JSON failed schema", parsed.error.message));
    }
    return ok({
      nodes: toRadiusNodes(parsed.data, query.name),
      disambiguationRequired: parsed.data.disambiguation_required,
    });
  }
}

/**
 * IntentSource port — where the "stated intent" of a change comes from.
 *
 * Ordered adapters are tried in turn (see CompositeIntentSource); the first one
 * that yields something wins and its `name` is recorded on the IntentModel so
 * the report can say "source: checkpoint-trailer". A source that has nothing to
 * say returns `ok(null)`, not an error.
 */
import type { Result } from "../domain/errors.js";
import type { IntentModel } from "../domain/model.js";

export interface PrContext {
  readonly repoPath: string;
  readonly base: string;
  readonly head: string;
  readonly prNumber: number | undefined;
  readonly prTitle: string | undefined;
  readonly prBody: string | undefined;
  /** "owner/repo", for `gh` lookups. */
  readonly repoSlug: string | undefined;
}

export interface IntentSource {
  readonly name: string;
  get(ctx: PrContext): Promise<Result<IntentModel | null>>;
}

