/**
 * Build an IntentModel from raw text. Pure — adapters gather the text, this
 * turns it into the comparable shape the scope-creep strategies expect.
 */
import { extractIssueRefs, extractKeywords } from "./intent-keywords.js";
import type { IntentModel } from "./model.js";

export interface RawIntent {
  readonly source: string;
  readonly title?: string | undefined;
  readonly body?: string | undefined;
  readonly extraReferences?: readonly string[] | undefined;
}

export function buildIntentModel(raw: RawIntent): IntentModel | null {
  const title = (raw.title ?? "").trim();
  const body = (raw.body ?? "").trim();
  const text = `${title}\n${body}`.trim();
  if (text.length === 0) return null;

  return {
    source: raw.source,
    title,
    body,
    keywords: extractKeywords(text),
    references: [...new Set([...extractIssueRefs(text), ...(raw.extraReferences ?? [])])],
  };
}

/**
 * Intent = the PR title + description. The universal fallback: every PR has one.
 */
import { ok, type Result } from "../../domain/errors.js";
import { buildIntentModel } from "../../domain/intent.js";
import type { IntentModel } from "../../domain/model.js";
import type { IntentSource, PrContext } from "../../ports/intent-source.js";

export class PrBodyIntentSource implements IntentSource {
  readonly name = "pr-body";

  async get(ctx: PrContext): Promise<Result<IntentModel | null>> {
    return ok(
      buildIntentModel({
        source: this.name,
        title: ctx.prTitle,
        body: ctx.prBody,
      }),
    );
  }
}

/**
 * Intent = the originating Entire session.
 *
 * `git log` the head commit for an `Entire-Checkpoint: <id>` trailer. If found,
 * that id becomes the range checkpoint, and — when the repo carries a captured
 * prompt at `.entire/intent/<id>.json` (`{ "prompt": "..." }` or
 * `{ "title": "...", "body": "..." }`) — that text is the stated intent, which
 * is the real ask, not a reconstruction.
 *
 * This is the "Connecting Graph findings with Checkpoint intent" direction from
 * the brief made concrete.
 */
import { readFile } from "node:fs/promises";
import path from "node:path";
import { execa } from "execa";
import { z } from "zod";
import { ok, type Result } from "../../domain/errors.js";
import { buildIntentModel } from "../../domain/intent.js";
import type { IntentModel } from "../../domain/model.js";
import type { IntentSource, PrContext } from "../../ports/intent-source.js";

const TRAILER_RE = /Entire-Checkpoint:\s*([A-Za-z0-9._-]+)/;

const capturedIntentSchema = z.object({
  prompt: z.string().optional(),
  title: z.string().optional(),
  body: z.string().optional(),
  summary: z.string().optional(),
});

export interface CheckpointTrailerOptions {
  readonly gitBinary?: string;
}

export class CheckpointTrailerIntentSource implements IntentSource {
  readonly name = "checkpoint-trailer";
  private readonly git: string;

  constructor(opts: CheckpointTrailerOptions = {}) {
    this.git = opts.gitBinary ?? "git";
  }

  async get(ctx: PrContext): Promise<Result<IntentModel | null>> {
    const id = await this.readTrailer(ctx);
    if (!id) return ok(null);

    const captured = await this.readCapturedIntent(ctx.repoPath, id);
    if (captured) {
      const model = buildIntentModel({
        source: this.name,
        title: captured.title ?? captured.summary,
        body: captured.body ?? captured.prompt,
        extraReferences: [id],
      });
      if (model) return ok(model);
    }

    // trailer present but no captured text: still useful — record the link,
    // fall back to the commit subject as a thin intent.
    const subject = await this.headSubject(ctx);
    return ok(
      buildIntentModel({
        source: this.name,
        title: subject,
        body: `Entire checkpoint ${id}`,
        extraReferences: [id],
      }),
    );
  }

  private async readTrailer(ctx: PrContext): Promise<string | null> {
    try {
      const { stdout } = await execa(
        this.git,
        ["-C", ctx.repoPath, "log", "-1", "--format=%B", ctx.head],
        { reject: true },
      );
      return TRAILER_RE.exec(stdout)?.[1] ?? null;
    } catch {
      return null;
    }
  }

  private async headSubject(ctx: PrContext): Promise<string | undefined> {
    try {
      const { stdout } = await execa(
        this.git,
        ["-C", ctx.repoPath, "log", "-1", "--format=%s", ctx.head],
        { reject: true },
      );
      return stdout.trim() || undefined;
    } catch {
      return undefined;
    }
  }

  private async readCapturedIntent(
    repoPath: string,
    id: string,
  ): Promise<z.infer<typeof capturedIntentSchema> | null> {
    for (const rel of [`.entire/intent/${id}.json`, `.entire/intents/${id}.json`]) {
      try {
        const raw = await readFile(path.resolve(repoPath, rel), "utf8");
        const parsed = capturedIntentSchema.safeParse(JSON.parse(raw));
        if (parsed.success) return parsed.data;
      } catch {
        // try the next location
      }
    }
    return null;
  }
}

/**
 * Intent = a linked issue. Parse `#123` / `Closes #123` from the PR body and
 * ask `gh` for the issue's title + body.
 */
import { execa } from "execa";
import { z } from "zod";
import { ok, type Result } from "../../domain/errors.js";
import { buildIntentModel } from "../../domain/intent.js";
import { extractIssueRefs } from "../../domain/intent-keywords.js";
import type { IntentModel } from "../../domain/model.js";
import type { IntentSource, PrContext } from "../../ports/intent-source.js";

const ghIssueSchema = z.object({ title: z.string(), body: z.string().nullable().default("") });

export interface GitHubIssueOptions {
  readonly ghBinary?: string;
}

export class GitHubIssueIntentSource implements IntentSource {
  readonly name = "github-issue";
  private readonly gh: string;

  constructor(opts: GitHubIssueOptions = {}) {
    this.gh = opts.ghBinary ?? "gh";
  }

  async get(ctx: PrContext): Promise<Result<IntentModel | null>> {
    const refs = extractIssueRefs(`${ctx.prTitle ?? ""}\n${ctx.prBody ?? ""}`).filter((r) =>
      r.startsWith("#"),
    );
    if (refs.length === 0) return ok(null);

    const number = refs[0]!.slice(1);
    try {
      const args = ["issue", "view", number, "--json", "title,body"];
      if (ctx.repoSlug) args.push("--repo", ctx.repoSlug);
      const { stdout } = await execa(this.gh, args, { reject: true });
      const parsed = ghIssueSchema.safeParse(JSON.parse(stdout));
      if (!parsed.success) return ok(null);
      const model: IntentModel | null = buildIntentModel({
        source: this.name,
        title: parsed.data.title,
        body: parsed.data.body,
        extraReferences: [`#${number}`],
      });
      return ok(model);
    } catch {
      return ok(null); // gh not available / not authed / issue not found — just skip
    }
  }
}

/**
 * Try each source in order; first non-null wins. Errors from one source are
 * swallowed (logged via `onSkip`) so a flaky `gh` never blocks the review.
 */
import { ok, type Result } from "../../domain/errors.js";
import type { IntentModel } from "../../domain/model.js";
import type { IntentSource, PrContext } from "../../ports/intent-source.js";

export class CompositeIntentSource implements IntentSource {
  readonly name = "composite";
  private readonly sources: readonly IntentSource[];
  private readonly onSkip: (name: string, reason: string) => void;

  constructor(
    sources: readonly IntentSource[],
    onSkip: (name: string, reason: string) => void = () => {},
  ) {
    this.sources = sources;
    this.onSkip = onSkip;
  }

  async get(ctx: PrContext): Promise<Result<IntentModel | null>> {
    for (const source of this.sources) {
      const res = await source.get(ctx);
      if (!res.ok) {
        this.onSkip(source.name, res.error.message);
        continue;
      }
      if (res.value) return ok(res.value);
      this.onSkip(source.name, "nothing to contribute");
    }
    return ok(null);
  }
}

/**
 * ReportSink port — where a rendered report goes.
 *   StdoutSink        — print it
 *   FileSink          — write it to a path
 *   GitHubCommentSink — upsert one PR comment (find its marker, edit or create)
 */
import type { Result } from "../domain/errors.js";
import type { RenderedReport } from "./renderer.js";

export interface ReportSink {
  readonly kind: string;
  publish(rendered: RenderedReport): Promise<Result<void>>;
}

import { ok, type Result } from "../../domain/errors.js";
import type { ReportSink } from "../../ports/report-sink.js";
import type { RenderedReport } from "../../ports/renderer.js";

export class StdoutSink implements ReportSink {
  readonly kind = "stdout";
  private readonly write: (s: string) => void;

  constructor(write: (s: string) => void = (s) => process.stdout.write(s)) {
    this.write = write;
  }

  async publish(rendered: RenderedReport): Promise<Result<void>> {
    this.write(rendered.body.endsWith("\n") ? rendered.body : `${rendered.body}\n`);
    return ok(undefined);
  }
}

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { BlastRadiusError, err, ok, type Result } from "../../domain/errors.js";
import type { ReportSink } from "../../ports/report-sink.js";
import type { RenderedReport } from "../../ports/renderer.js";

export class FileSink implements ReportSink {
  readonly kind = "file";
  private readonly filePath: string;

  constructor(filePath: string) {
    this.filePath = filePath;
  }

  async publish(rendered: RenderedReport): Promise<Result<void>> {
    try {
      await mkdir(path.dirname(path.resolve(this.filePath)), { recursive: true });
      await writeFile(this.filePath, rendered.body, "utf8");
      return ok(undefined);
    } catch (e) {
      return err(BlastRadiusError.sink(`could not write ${this.filePath}`, (e as Error).message));
    }
  }
}

/**
 * Upsert exactly one PR comment.
 *
 * Finds the previous Blast Radius comment by its marker and PATCHes it;
 * otherwise POSTs a new one. Re-running on every push therefore updates one
 * comment instead of burying the thread. Uses `gh api` (argv, never a shell
 * string); auth is whatever `gh`/`GH_TOKEN` already provides.
 */
import { execa } from "execa";
import { z } from "zod";
import { BlastRadiusError, err, ok, type Result } from "../../domain/errors.js";
import type { ReportSink } from "../../ports/report-sink.js";
import type { RenderedReport } from "../../ports/renderer.js";

const commentsSchema = z.array(z.object({ id: z.number(), body: z.string().nullable() }));

export interface GitHubCommentSinkOptions {
  readonly repoSlug: string;
  readonly prNumber: number;
  readonly ghBinary?: string;
}

export class GitHubCommentSink implements ReportSink {
  readonly kind = "github-comment";
  private readonly slug: string;
  private readonly pr: number;
  private readonly gh: string;

  constructor(opts: GitHubCommentSinkOptions) {
    this.slug = opts.repoSlug;
    this.pr = opts.prNumber;
    this.gh = opts.ghBinary ?? "gh";
  }

  async publish(rendered: RenderedReport): Promise<Result<void>> {
    if (!rendered.marker) {
      return err(BlastRadiusError.sink("github-comment sink needs a marked report (markdown)"));
    }
    try {
      const existingId = await this.findExisting(rendered.marker);
      if (existingId !== null) {
        await this.api("PATCH", `repos/${this.slug}/issues/comments/${existingId}`, rendered.body);
      } else {
        await this.api("POST", `repos/${this.slug}/issues/${this.pr}/comments`, rendered.body);
      }
      return ok(undefined);
    } catch (e) {
      return err(
        BlastRadiusError.sink("could not upsert PR comment", (e as Error).message.slice(0, 300)),
      );
    }
  }

  private async findExisting(marker: string): Promise<number | null> {
    const { stdout } = await execa(
      this.gh,
      ["api", `repos/${this.slug}/issues/${this.pr}/comments?per_page=100`],
      { reject: true },
    );
    const parsed = commentsSchema.safeParse(JSON.parse(stdout));
    if (!parsed.success) return null;
    return parsed.data.find((c) => c.body?.includes(marker))?.id ?? null;
  }

  private async api(method: "POST" | "PATCH", path: string, body: string): Promise<void> {
    await execa(this.gh, ["api", "--method", method, path, "-f", `body=${body}`], { reject: true });
  }
}

