/**
 * The fully-resolved configuration for one `review` run. The CLI builds this
 * (merging flags, env, and GitHub Actions context); the composition root turns
 * it into wired adapters. Nothing downstream reads `process.env`.
 */
import { z } from "zod";

export const renderFormat = z.enum(["markdown", "json", "sarif"]);
export type RenderFormatName = z.infer<typeof renderFormat>;

export const outputTarget = z.object({
  format: renderFormat,
  /** file path, "stdout", or "pr-comment". */
  to: z.string(),
});
export type OutputTarget = z.infer<typeof outputTarget>;

export const reviewConfigSchema = z.object({
  repoPath: z.string().default("."),
  range: z.object({ base: z.string(), head: z.string() }),

  graph: z.object({
    mode: z.enum(["cli", "fixture"]).default("cli"),
    binary: z.string().default("entire-graph"),
    fixtureDir: z.string().optional(),
    useHead: z.boolean().default(false),
    profile: z.enum(["syntax-only", "fast", "full"]).default("full"),
    impactDepth: z.union([z.literal(1), z.literal(2)]).default(2),
    timeoutMs: z.number().int().positive().default(240_000),
  }),

  intent: z.object({
    order: z
      .array(z.enum(["checkpoint-trailer", "github-issue", "pr-body"]))
      .default(["checkpoint-trailer", "github-issue", "pr-body"]),
  }),

  pr: z.object({
    number: z.number().int().optional(),
    title: z.string().optional(),
    body: z.string().optional(),
    repoSlug: z.string().optional(),
  }),

  scopeCreep: z.object({
    keywordMaxOverlap: z.number().min(0).max(1).optional(),
    keywordMinDependents: z.number().int().nonnegative().optional(),
    dependentsThreshold: z.number().int().positive().optional(),
  }),

  testSelection: z.object({
    maxTests: z.number().int().positive().default(12),
  }),

  summary: z.object({
    moduleDepth: z.number().int().positive().default(2),
  }),

  render: z.object({
    repoBlobUrlBase: z.string().optional(),
    suiteTestCount: z.number().int().positive().optional(),
    toolUrl: z.string().optional(),
  }),

  outputs: z.array(outputTarget).min(1),
  failOnFindings: z.boolean().default(false),
});

export type ReviewConfig = z.infer<typeof reviewConfigSchema>;

export function parseReviewConfig(input: unknown): ReviewConfig {
  return reviewConfigSchema.parse(input);
}

/**
 * The `review` use-case — the pipeline spelled out.
 *
 *   diff ─▶ impact per changed symbol ─▶ blast radius
 *                                          │
 *                     ┌────────────────────┼─────────────────────┐
 *                     ▼                    ▼                     ▼
 *              scope-creep check     test selection        radius summary
 *                     └────────────────────┼─────────────────────┘
 *                                          ▼
 *                                   AnalysisReport ─▶ render ─▶ publish
 *
 * Depends only on ports. The composition root supplies the implementations.
 */
import { computeBlastRadius } from "../domain/blast-radius.js";
import { type BlastRadiusError, isErr, ok, type Result, settle } from "../domain/errors.js";
import type { AnalysisReport, RadiusNode } from "../domain/model.js";
import { reportBuilder } from "../domain/report.js";
import type { ScopeCreepStrategy } from "../domain/scope-creep/index.js";
import { summarizeRadius, type SummaryOptions } from "../domain/summary.js";
import { selectTests, type TestSelectionOptions } from "../domain/test-selection.js";
import type { CommitRange, GraphProvider } from "../ports/graph-provider.js";
import { impactQueryFor } from "../ports/graph-provider.js";
import type { IntentSource, PrContext } from "../ports/intent-source.js";
import type { ReportSink } from "../ports/report-sink.js";
import type { Renderer } from "../ports/renderer.js";

export type LogLevel = "info" | "warn" | "error";

export interface ReviewDeps {
  readonly graph: GraphProvider;
  readonly intent: IntentSource;
  readonly scopeCreep: ScopeCreepStrategy;
  /** one renderer + sink per configured output. */
  readonly outputs: readonly { renderer: Renderer; sink: ReportSink }[];
  readonly log: (level: LogLevel, message: string) => void;
  readonly clock?: () => Date;
}

export interface ReviewRequest {
  readonly range: CommitRange;
  readonly prContext: PrContext;
  readonly testSelection?: TestSelectionOptions;
  readonly summary?: SummaryOptions;
}

export interface ReviewOutcome {
  readonly report: AnalysisReport;
  readonly publishedTo: string[];
  readonly hasFindings: boolean;
}

export async function runReview(
  deps: ReviewDeps,
  req: ReviewRequest,
): Promise<Result<ReviewOutcome>> {
  const { graph, intent, scopeCreep, log } = deps;

  /* 1 — changed symbols ------------------------------------------------ */
  const diffRes = await graph.diff(req.range);
  if (isErr(diffRes)) return diffRes;
  const changeSet = diffRes.value;
  log("info", `${changeSet.symbols.length} changed symbol(s) across ${changeSet.changedFiles.length} file(s)`);

  /* 2 — impact per symbol -------------------------------------------- */
  const impactResults = await Promise.all(
    changeSet.symbols.map((s) => graph.impact(impactQueryFor(s.ref))),
  );
  const { values: impacts, errors: impactErrors } = settle<
    { nodes: readonly RadiusNode[]; disambiguationRequired: boolean },
    BlastRadiusError
  >(impactResults);
  for (const e of impactErrors) log("warn", `impact skipped: ${e.message}`);

  const nodeLists = impacts.map((i) => i.nodes);

  /* 3 — blast radius ------------------------------------------------- */
  const radius = computeBlastRadius(changeSet.symbols, nodeLists);
  log("info", `blast radius: ${radius.nodes.length} node(s)`);

  /* 4 — intent ----------------------------------------------------- */
  const intentRes = await intent.get(req.prContext);
  const intentModel = isErr(intentRes) ? null : intentRes.value;
  if (isErr(intentRes)) log("warn", `intent unavailable: ${intentRes.error.message}`);
  else log("info", intentModel ? `intent from ${intentModel.source}` : "no stated intent found");

  /* 5 — fan out: scope / tests / summary --------------------------- */
  const findings = scopeCreep.evaluate({ changeSet, intent: intentModel, radius });
  const testPlan = selectTests(radius, changeSet.symbols, req.testSelection);
  const summary = summarizeRadius(radius, req.summary);

  /* 6 — report --------------------------------------------------- */
  const report = reportBuilder.build({
    range: { base: req.range.base, head: req.range.head, checkpoint: changeSet.checkpoint },
    changeSet,
    intent: intentModel,
    radius,
    summary,
    findings,
    testPlan,
    ...(deps.clock ? { now: deps.clock() } : {}),
  });

  /* 7 — render + publish -------------------------------------- */
  const publishedTo: string[] = [];
  for (const { renderer, sink } of deps.outputs) {
    const rendered = renderer.render(report);
    const res = await sink.publish(rendered);
    if (isErr(res)) {
      log("error", `publish to ${sink.kind} failed: ${res.error.message}`);
      return res;
    }
    publishedTo.push(`${renderer.format}→${sink.kind}`);
  }

  return ok({ report, publishedTo, hasFindings: findings.length > 0 });
}

/**
 * Composition root — the ONLY file that imports `adapters/`.
 *
 * Turns a resolved `ReviewConfig` into wired `ReviewDeps` + `ReviewRequest`.
 * Swapping an implementation (fixture vs real graph, stdout vs PR comment) is a
 * choice made here from config, nowhere else.
 */
import { EntireGraphCliAdapter } from "./adapters/graph/entire-graph-cli.js";
import { FixtureGraphAdapter } from "./adapters/graph/fixture.js";
import { CheckpointTrailerIntentSource } from "./adapters/intent/checkpoint-trailer.js";
import { CompositeIntentSource } from "./adapters/intent/composite.js";
import { GitHubIssueIntentSource } from "./adapters/intent/github-issue.js";
import { PrBodyIntentSource } from "./adapters/intent/pr-body.js";
import { JsonRenderer } from "./adapters/render/json.js";
import { MarkdownRenderer } from "./adapters/render/markdown.js";
import { SarifRenderer } from "./adapters/render/sarif.js";
import { FileSink } from "./adapters/sink/file.js";
import { GitHubCommentSink } from "./adapters/sink/github-comment.js";
import { StdoutSink } from "./adapters/sink/stdout.js";
import type { ReviewConfig } from "./app/config.js";
import type { LogLevel, ReviewDeps, ReviewRequest } from "./app/review.js";
import { BlastRadiusError } from "./domain/errors.js";
import { defaultScopeCreepStrategy } from "./domain/scope-creep/index.js";
import type { GraphProvider } from "./ports/graph-provider.js";
import type { IntentSource } from "./ports/intent-source.js";
import type { ReportSink } from "./ports/report-sink.js";
import type { Renderer } from "./ports/renderer.js";

export type Logger = (level: LogLevel, message: string) => void;

export interface WiredReview {
  readonly deps: ReviewDeps;
  readonly request: ReviewRequest;
}

export function composeReview(config: ReviewConfig, log: Logger = () => {}): WiredReview {
  const graph = buildGraph(config);
  const intent = buildIntent(config, log);
  const outputs = buildOutputs(config);

  const deps: ReviewDeps = {
    graph,
    intent,
    scopeCreep: defaultScopeCreepStrategy(config.scopeCreep),
    outputs,
    log,
  };

  const request: ReviewRequest = {
    range: config.range,
    prContext: {
      repoPath: config.repoPath,
      base: config.range.base,
      head: config.range.head,
      prNumber: config.pr.number,
      prTitle: config.pr.title,
      prBody: config.pr.body,
      repoSlug: config.pr.repoSlug,
    },
    testSelection: { maxTests: config.testSelection.maxTests },
    summary: { moduleDepth: config.summary.moduleDepth },
  };

  return { deps, request };
}

/* ------------------------------------------------------------- builders --- */

function buildGraph(config: ReviewConfig): GraphProvider {
  if (config.graph.mode === "fixture") {
    if (!config.graph.fixtureDir) {
      throw BlastRadiusError.config("graph.mode is 'fixture' but no fixtureDir was given");
    }
    return new FixtureGraphAdapter(config.graph.fixtureDir);
  }
  return new EntireGraphCliAdapter({
    binary: config.graph.binary,
    repo: config.repoPath,
    head: config.graph.useHead,
    profile: config.graph.profile,
    timeoutMs: config.graph.timeoutMs,
    impactDepth: config.graph.impactDepth,
  });
}

function buildIntent(config: ReviewConfig, log: Logger): IntentSource {
  const byName: Record<string, () => IntentSource> = {
    "checkpoint-trailer": () => new CheckpointTrailerIntentSource(),
    "github-issue": () => new GitHubIssueIntentSource(),
    "pr-body": () => new PrBodyIntentSource(),
  };
  const sources = config.intent.order.map((n) => byName[n]!());
  return new CompositeIntentSource(sources, (name, reason) =>
    log("info", `intent source ${name}: ${reason}`),
  );
}

function buildRenderer(format: "markdown" | "json" | "sarif", config: ReviewConfig): Renderer {
  switch (format) {
    case "markdown":
      return new MarkdownRenderer({
        ...(config.render.repoBlobUrlBase !== undefined
          ? { repoBlobUrlBase: config.render.repoBlobUrlBase }
          : {}),
        ...(config.render.suiteTestCount !== undefined
          ? { suiteTestCount: config.render.suiteTestCount }
          : {}),
        ...(config.render.toolUrl !== undefined ? { toolUrl: config.render.toolUrl } : {}),
      });
    case "json":
      return new JsonRenderer();
    case "sarif":
      return new SarifRenderer();
  }
}

function buildSink(to: string, config: ReviewConfig): ReportSink {
  if (to === "stdout") return new StdoutSink();
  if (to === "pr-comment") {
    if (!config.pr.number || !config.pr.repoSlug) {
      throw BlastRadiusError.config("output 'pr-comment' needs pr.number and pr.repoSlug");
    }
    return new GitHubCommentSink({ repoSlug: config.pr.repoSlug, prNumber: config.pr.number });
  }
  return new FileSink(to);
}

function buildOutputs(config: ReviewConfig): { renderer: Renderer; sink: ReportSink }[] {
  return config.outputs.map((o) => ({
    renderer: buildRenderer(o.format, config),
    sink: buildSink(o.to, config),
  }));
}

/**
 * Read GitHub Actions context (event payload + env) into the fields the CLI
 * needs. Pure-ish: it only reads the env and one file the runner points at.
 */
import { readFileSync } from "node:fs";

export interface GitHubContext {
  base: string | undefined;
  head: string | undefined;
  prNumber: number | undefined;
  prTitle: string | undefined;
  prBody: string | undefined;
  repoSlug: string | undefined;
  repoBlobUrlBase: string | undefined;
}

export function readGitHubContext(env: NodeJS.ProcessEnv = process.env): GitHubContext | null {
  if (!env.GITHUB_ACTIONS) return null;

  const repoSlug = env.GITHUB_REPOSITORY;
  const server = env.GITHUB_SERVER_URL ?? "https://github.com";

  let base: string | undefined;
  let head: string | undefined;
  let prNumber: number | undefined;
  let prTitle: string | undefined;
  let prBody: string | undefined;

  if (env.GITHUB_EVENT_PATH) {
    try {
      const event = JSON.parse(readFileSync(env.GITHUB_EVENT_PATH, "utf8")) as {
        pull_request?: {
          number?: number;
          title?: string;
          body?: string | null;
          base?: { sha?: string };
          head?: { sha?: string };
        };
      };
      const pr = event.pull_request;
      if (pr) {
        prNumber = pr.number;
        prTitle = pr.title;
        prBody = pr.body ?? undefined;
        base = pr.base?.sha;
        head = pr.head?.sha;
      }
    } catch {
      // fall through to env-only
    }
  }

  head ??= env.GITHUB_SHA;
  const repoBlobUrlBase =
    repoSlug && head ? `${server}/${repoSlug}/blob/${head}` : undefined;

  return {
    base,
    head,
    prNumber,
    prTitle,
    prBody,
    repoSlug,
    repoBlobUrlBase,
  };
}

#!/usr/bin/env node
/**
 * Blast Radius CLI. Parses flags, folds in GitHub Actions context when present,
 * builds a `ReviewConfig`, and runs the `review` use-case through the
 * composition root.
 */
import { Command, Option } from "commander";
import { readGitHubContext } from "./app/github-context.js";
import { parseReviewConfig, type OutputTarget } from "./app/config.js";
import { runReview } from "./app/review.js";
import { composeReview, type Logger } from "./composition-root.js";
import { BlastRadiusError } from "./domain/errors.js";

const program = new Command();

program
  .name("blast-radius")
  .description("Impact-aware PR review powered by Entire Graph")
  .version("0.1.0");

program
  .command("review")
  .description("analyse a commit range and report the blast radius, scope drift and test set")
  .option("--base <ref>", "base revision")
  .option("--head <ref>", "head revision")
  .option("--repo <path>", "repository path", ".")
  .option("--fixture <dir>", "use recorded entire-graph JSON instead of the binary")
  .option("--entire-graph <bin>", "entire-graph binary name or path", "entire-graph")
  .option("--graph-head", "query entire-graph's committed tree (--head)")
  .addOption(
    new Option("--profile <p>", "entire-graph parse profile")
      .choices(["syntax-only", "fast", "full"])
      .default("full"),
  )
  .option("--format <fmt...>", "output formats: markdown, json, sarif", ["markdown"])
  .option("--markdown-out <file>", "write markdown here instead of stdout")
  .option("--json-out <file>", "write json here")
  .option("--sarif-out <file>", "write sarif here")
  .option("--comment", "upsert the markdown report as a PR comment")
  .option("--intent-source <list>", "comma list: checkpoint-trailer,github-issue,pr-body")
  .option("--pr <number>", "pull request number", (v) => parseInt(v, 10))
  .option("--pr-title <s>", "pull request title (intent source)")
  .option("--pr-body <s>", "pull request body (intent source)")
  .option("--repo-slug <owner/repo>", "for gh lookups and blob links")
  .option("--blob-url-base <url>", "https://host/owner/repo/blob/<sha> for clickable links")
  .option("--suite-test-count <n>", "total tests in the suite, for '6 of ~N'", (v) => parseInt(v, 10))
  .option("--dependents-threshold <n>", "wide-reaching-change threshold", (v) => parseInt(v, 10))
  .option("--max-tests <n>", "cap on recommended tests", (v) => parseInt(v, 10))
  .option("--fail-on-findings", "exit non-zero when scope findings exist")
  .option("--quiet", "suppress progress logs on stderr")
  .action(async (opts) => {
    const gh = readGitHubContext();

    const base = opts.base ?? gh?.base ?? "origin/main";
    const head = opts.head ?? gh?.head ?? "HEAD";

    const outputs: OutputTarget[] = [];
    for (const fmt of opts.format as string[]) {
      if (fmt === "markdown") {
        outputs.push({
          format: "markdown",
          to: opts.markdownOut ?? (opts.comment ? "pr-comment" : "stdout"),
        });
      } else if (fmt === "json") {
        outputs.push({ format: "json", to: opts.jsonOut ?? "stdout" });
      } else if (fmt === "sarif") {
        outputs.push({ format: "sarif", to: opts.sarifOut ?? "blast-radius.sarif" });
      }
    }
    if (opts.jsonOut && !outputs.some((o) => o.format === "json"))
      outputs.push({ format: "json", to: opts.jsonOut });
    if (opts.sarifOut && !outputs.some((o) => o.format === "sarif"))
      outputs.push({ format: "sarif", to: opts.sarifOut });

    const log: Logger = opts.quiet
      ? () => {}
      : (level, msg) => process.stderr.write(`[blast-radius] ${level}: ${msg}\n`);

    try {
      const config = parseReviewConfig({
        repoPath: opts.repo,
        range: { base, head },
        graph: {
          mode: opts.fixture ? "fixture" : "cli",
          binary: opts.entireGraph,
          fixtureDir: opts.fixture,
          useHead: Boolean(opts.graphHead),
          profile: opts.profile,
        },
        intent: {
          order: opts.intentSource
            ? (opts.intentSource as string).split(",").map((s) => s.trim())
            : undefined,
        },
        pr: {
          number: opts.pr ?? gh?.prNumber,
          title: opts.prTitle ?? gh?.prTitle,
          body: opts.prBody ?? gh?.prBody,
          repoSlug: opts.repoSlug ?? gh?.repoSlug,
        },
        scopeCreep: {
          ...(opts.dependentsThreshold ? { dependentsThreshold: opts.dependentsThreshold } : {}),
        },
        testSelection: { ...(opts.maxTests ? { maxTests: opts.maxTests } : {}) },
        summary: {},
        render: {
          ...(opts.blobUrlBase || gh?.repoBlobUrlBase
            ? { repoBlobUrlBase: opts.blobUrlBase ?? gh?.repoBlobUrlBase }
            : {}),
          ...(opts.suiteTestCount ? { suiteTestCount: opts.suiteTestCount } : {}),
          toolUrl: "[Blast Radius](https://github.com/entire-hackathon/blast-radius)",
        },
        outputs,
        failOnFindings: Boolean(opts.failOnFindings),
      });

      const { deps, request } = composeReview(config, log);
      const result = await runReview(deps, request);

      if (!result.ok) {
        process.stderr.write(`\n✖ ${result.error.message}\n`);
        if (result.error.detail) process.stderr.write(`  ${result.error.detail}\n`);
        process.exitCode = 2;
        return;
      }

      log("info", `published: ${result.value.publishedTo.join(", ")}`);
      if (config.failOnFindings && result.value.hasFindings) {
        process.stderr.write(`\n✖ ${result.value.report.findings.length} scope finding(s)\n`);
        process.exitCode = 1;
      }
    } catch (e) {
      const msg = e instanceof BlastRadiusError ? e.message : (e as Error).message;
      process.stderr.write(`\n✖ ${msg}\n`);
      process.exitCode = 2;
    }
  });

program.parseAsync().catch((e) => {
  process.stderr.write(`\n✖ ${(e as Error).message}\n`);
  process.exitCode = 2;
});

