  query(sql: string): Row[] {
    const key = sql.trim().toLowerCase();
    return store.get(key) ?? [];
  }

  /** test seam */
  seed(sql: string, rows: Row[]): void {
    store.set(sql.trim().toLowerCase(), rows);
