/** In-memory per-key token bucket. */
export class TokenBucketRateLimiter {
  private readonly capacity: number;
  private readonly refillPerSec: number;
  private readonly buckets = new Map<string, { tokens: number; last: number }>();

  constructor(capacity = 10, refillPerSec = 1) {
    this.capacity = capacity;
    this.refillPerSec = refillPerSec;
  }

  /** Try to spend one token for `key`. Returns false when the bucket is empty. */
  take(key: string, now: number = Date.now()): boolean {
    const bucket = this.buckets.get(key) ?? { tokens: this.capacity, last: now };
    const elapsed = (now - bucket.last) / 1000;
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.refillPerSec);
    bucket.last = now;
    if (bucket.tokens < 1) {
      this.buckets.set(key, bucket);
      return false;
    }
    bucket.tokens -= 1;
    this.buckets.set(key, bucket);
    return true;
  }
}

export const redirectRateLimiter = new TokenBucketRateLimiter(20, 5);

/** Options accepted by `Database.query`. */
export interface QueryOptions {
  /** abort the query after this many milliseconds. */
  timeoutMs?: number;
  /** route to the read replica. */
  readonly?: boolean;
}

/** The one place SQL actually runs. Everything goes through here. */
import type { QueryOptions } from "./types.js";

export interface Row {
  [column: string]: string | number | null;
}

const store = new Map<string, Row[]>();

export class Database {
  /** Run a query and return the rows. */
  query(sql: string, opts: QueryOptions = {}): Row[] {
    const key = sql.trim().toLowerCase();
    if (opts.timeoutMs !== undefined && opts.timeoutMs <= 0) return [];
    return store.get(key) ?? [];
  }

  /** test seam */
  seed(sql: string, rows: Row[]): void {
    store.set(sql.trim().toLowerCase(), rows);
  }
}

