}

export class LinkRepo {
  /** Look up a link by its slug. */
  byId(slug: string, opts?: QueryOptions): Link | null {
    const rows = db.query(`select * from links where slug = '${slug}'`, opts);
    return rows[0] ? toLink(rows[0]) : null;
  }

  /** Persist a new link. */
