describe("LinkRepo", () => {
  it("reads a link by slug", () => {
    expect(linkRepo.byId("xy")).toEqual({ slug: "xy", url: "https://x.com", hits: 3 });
  });

  it("returns null for a missing slug", () => {
    expect(linkRepo.byId("missing")).toBeNull();
  });

  it("saves a link", () => {
    linkRepo.save({ slug: "new", url: "https://new.example", hits: 0 });
  });

  it("increments the hit counter", () => {
    linkRepo.hit("xy");
  });
});

