1	/**
2	 * Fold the per-changed-symbol impact node lists into one blast radius.
3	 *
4	 * Rules:
5	 *  - dedupe by (file, qualifiedName): the same downstream symbol reached from
6	 *    two changed symbols is one node, keeping the SHORTEST distance and the
7	 *    union of origin symbols;
8	 *  - a node that is itself one of the changed symbols is dropped (it is the
9	 *    origin, not the blast);
10	 *  - section totals count distinct nodes per section after dedupe.
11	 */
12	import type { BlastRadius, ChangedSymbol, RadiusNode, RadiusSection } from "./model.js";
13	import { symbolKey } from "./model.js";
14	
15	const SECTIONS: readonly RadiusSection[] = [
16	  "callers",
17	  "callees",
18	  "type_consumers",
19	  "data_flows",
20	  "co_changes",
21	  "siblings",
22	];
23	
24	function emptyTotals(): Record<RadiusSection, number> {
25	  return { callers: 0, callees: 0, type_consumers: 0, data_flows: 0, co_changes: 0, siblings: 0 };
26	}
27	
28	function mergeNode(existing: RadiusNode, incoming: RadiusNode): RadiusNode {
29	  const origins = new Set([...existing.originSymbols, ...incoming.originSymbols]);
30	  const closer = incoming.distance < existing.distance ? incoming : existing;
31	  return {
32	    ...closer,
33	    originSymbols: [...origins],
34	    // keep the richer via chain / call site if the closer one lacks it
35	    viaChain: closer.viaChain.length > 0 ? closer.viaChain : existing.viaChain,
36	    callSite: closer.callSite ?? existing.callSite,
37	    isTest: existing.isTest || incoming.isTest,
38	  };
39	}
40	
41	export function computeBlastRadius(
42	  origin: readonly ChangedSymbol[],
43	  nodeLists: readonly (readonly RadiusNode[])[],
44	): BlastRadius {
45	  const originKeys = new Set(origin.map((s) => symbolKey(s.ref)));
46	  const originNames = new Set(origin.map((s) => s.ref.qualifiedName));
47	  // siblings of a *newly added* symbol are just the other members of the same
48	  // new class/module — they didn't change and tell a reviewer nothing.
49	  const addedNames = new Set(
50	    origin.filter((s) => s.changeType === "added").map((s) => s.ref.qualifiedName),
51	  );
52	  const byKey = new Map<string, RadiusNode>();
53	
54	  for (const list of nodeLists) {
55	    for (const node of list) {
56	      if (node.ref.external) {
57	        // external callees (fmt.Errorf, etc.) are noise for a review summary
58	        if (node.section === "callees") continue;
59	      }
60	      if (node.section === "siblings" && node.originSymbols.every((o) => addedNames.has(o))) {
61	        continue;
62	      }
63	      const key = symbolKey(node.ref);
64	      // a changed symbol is the origin of the blast, never part of it; match on
65	      // the (file, name) key, falling back to the qualified name alone so a
66	      // cosmetically different path (./ prefix, case) still excludes it.
67	      if (originKeys.has(key) || originNames.has(node.ref.qualifiedName)) continue;
68	      const existing = byKey.get(key);
69	      byKey.set(key, existing ? mergeNode(existing, node) : node);
70	    }
71	  }
72	
73	  const nodes = [...byKey.values()].sort(
74	    (a, b) => a.distance - b.distance || a.ref.qualifiedName.localeCompare(b.ref.qualifiedName),
75	  );
76	
77	  const sectionTotals = emptyTotals();
78	  for (const node of nodes) sectionTotals[node.section] += 1;
79	
80	  return { origin: [...origin], nodes, sectionTotals };
81	}
82	
83	/** Nodes that sit on a caller path (what a reviewer most wants to see). */
84	export function upstreamNodes(radius: BlastRadius): RadiusNode[] {
85	  return radius.nodes.filter((n) => n.section === "callers");
86	}
87	
88	export { SECTIONS as RADIUS_SECTIONS };
