{
  "name": "blast-radius",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "bin": { "blast-radius": "dist/cli.js" },
  "engines": { "node": ">=20" },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "dev": "tsx src/cli.ts",
    "test": "vitest run",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "commander": "^12.1.0",
    "execa": "^9.5.2",
    "zod": "^3.24.1"
  },
  "devDependencies": {
    "@types/node": "^22.10.5",
    "tsx": "^4.19.2",
    "typescript": "^5.7.3",
    "vitest": "^2.1.8"
  }
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: { include: ["test/**/*.test.ts"], environment: "node" },
});

/** Domain value objects — the vocabulary every stage speaks. Pure. */

export interface SymbolRef {
  readonly name: string;
  readonly qualifiedName: string;
  readonly kind: string | undefined;
  readonly file: string | undefined;
  readonly line: number | undefined;
  readonly external: boolean;
}

export type ChangeType =
  | "added"
  | "removed"
  | "renamed"
  | "signature_changed"
  | "body_changed"
  | "unknown";

export interface ChangedSymbol {
  readonly ref: SymbolRef;
  readonly changeType: ChangeType;
  readonly dependentsCount: number;
  readonly oldSignature: string | undefined;
  readonly newSignature: string | undefined;
}

export interface ChangeSet {
  readonly base: string;
  readonly head: string;
  readonly checkpoint: string | undefined;
  readonly symbols: readonly ChangedSymbol[];
  readonly changedFiles: readonly string[];
}

export type RadiusSection =
  | "callers"
  | "callees"
  | "type_consumers"
  | "data_flows"
  | "co_changes"
  | "siblings";

export interface RadiusNode {
  readonly ref: SymbolRef;
  readonly section: RadiusSection;
  readonly relation: string;
  readonly distance: number;
  readonly viaChain: readonly string[];
  readonly originSymbols: readonly string[];
  readonly isTest: boolean;
}

export interface BlastRadius {
  readonly origin: readonly ChangedSymbol[];
  readonly nodes: readonly RadiusNode[];
  readonly sectionTotals: Readonly<Record<RadiusSection, number>>;
}

export interface IntentModel {
  readonly source: string;
  readonly text: string;
  readonly keywords: readonly string[];
}

export type Severity = "high" | "medium" | "low";

export interface Finding {
  readonly symbol: SymbolRef;
  readonly severity: Severity;
  readonly reason: string;
  readonly dependentsCount: number;
  readonly evidence: readonly string[];
}

export interface TestCandidate {
  readonly ref: SymbolRef;
  readonly distance: number;
  readonly covers: readonly string[];
}

export interface TestPlan {
  readonly framework: string;
  readonly selected: readonly TestCandidate[];
  readonly command: string | null;
  readonly coverageGaps: readonly string[];
}

export interface AnalysisReport {
  readonly schemaVersion: "1.0.0";
  readonly generatedAt: string;
  readonly range: { base: string; head: string; checkpoint: string | undefined };
  readonly intent: IntentModel | null;
  readonly changedSymbols: readonly ChangedSymbol[];
  readonly radius: BlastRadius;
  readonly findings: readonly Finding[];
  readonly testPlan: TestPlan;
}

export function symbolKey(ref: Pick<SymbolRef, "qualifiedName" | "file">): string {
  return `${ref.file ?? "?"}::${ref.qualifiedName}`;
}

export function loc(ref: Pick<SymbolRef, "file" | "line">): string | undefined {
  if (!ref.file) return undefined;
  return ref.line ? `${ref.file}:${ref.line}` : ref.file;
}

/**
 * Lenient zod schemas for the raw JSON that `entire graph` emits.
 * The graph schema is frozen-but-additive, so: passthrough everywhere,
 * most fields optional. Everything that enters the domain is parsed here first.
 */
import { z } from "zod";

export const rawEntityChange = z
  .object({
    type: z.string(),
    kind: z.string(),
    name: z.string(),
    new_name: z.string().optional(),
    old_signature: z.string().optional(),
    new_signature: z.string().optional(),
    new_path: z.string().optional(),
    before_start_line: z.number().int().optional(),
    after_start_line: z.number().int().optional(),
    dependents_count: z.number().int().default(0),
    reconciliation: z.string().optional(),
  })
  .passthrough();

export const rawFileChange = z
  .object({
    path: z.string(),
    status: z.string(),
    language: z.string().optional(),
    changes: z.array(rawEntityChange).default([]),
  })
  .passthrough();

export const rawDiffResult = z
  .object({
    base: z.string(),
    head: z.string(),
    checkpoint: z.string().optional(),
    files: z.array(rawFileChange).default([]),
  })
  .passthrough();
export type RawDiffResult = z.infer<typeof rawDiffResult>;

export const rawEndpoint = z
  .object({
    id: z.string().default(""),
    name: z.string().default(""),
    qualified_name: z.string().optional(),
    kind: z.string().optional(),
    file_path: z.string().optional(),
    start_line: z.number().int().optional(),
    external: z.boolean().optional(),
  })
  .passthrough();

export const rawImpactEntry = z
  .object({
    endpoint: rawEndpoint,
    relation: z.string().optional(),
    direction: z.string().optional(),
    depth: z.number().int().optional(),
    via: z.string().optional(),
  })
  .passthrough();

export const rawImpactSection = z
  .object({ total: z.number().int().default(0), entries: z.array(rawImpactEntry).default([]) })
  .passthrough();

export const rawImpactResult = z
  .object({
    query: z.string().default(""),
    disambiguation_required: z.boolean().default(false),
    callers: rawImpactSection.default({ total: 0, entries: [] }),
    callees: rawImpactSection.default({ total: 0, entries: [] }),
    type_consumers: rawImpactSection.default({ total: 0, entries: [] }),
    data_flows: rawImpactSection.default({ total: 0, entries: [] }),
    co_changes: rawImpactSection.default({ total: 0, entries: [] }),
    siblings: rawImpactSection.default({ total: 0, entries: [] }),
  })
  .passthrough();
export type RawImpactResult = z.infer<typeof rawImpactResult>;

export const IMPACT_SECTIONS = [
  "callers",
  "callees",
  "type_consumers",
  "data_flows",
  "co_changes",
  "siblings",
] as const;
export type ImpactSectionName = (typeof IMPACT_SECTIONS)[number];

/** Pure mappers: validated raw `entire graph` JSON → domain value objects. */
import type { RawDiffResult, RawImpactResult, ImpactSectionName } from "./graph-schema.js";
import { IMPACT_SECTIONS } from "./graph-schema.js";
import type {
  ChangeSet,
  ChangeType,
  ChangedSymbol,
  RadiusNode,
  RadiusSection,
  SymbolRef,
} from "./model.js";

const TEST_FILE = [
  /(^|\/)__tests__\//,
  /(^|\/)tests?\//,
  /\.(test|spec)\.[cm]?[jt]sx?$/,
  /_test\.go$/,
  /(^|\/)test_[^/]+\.py$/,
];
const TEST_NAME = [/^Test[A-Z_]/, /^test_/, /_test$/];

function isTest(ref: SymbolRef): boolean {
  const f = (ref.file ?? "").replace(/\\/g, "/");
  if (TEST_FILE.some((re) => re.test(f))) return true;
  return TEST_NAME.some((re) => re.test(ref.name));
}

const CHANGE_TYPE: Record<string, ChangeType> = {
  added: "added",
  removed: "removed",
  renamed: "renamed",
  signature_changed: "signature_changed",
  body_changed: "body_changed",
};
const NON_SYMBOL = new Set(["module", "file", "section", "document"]);
const NON_CODE_LANG = new Set(["Markdown", "JSON", "YAML", "TOML", "XML", "HTML"]);
const NOISE_MEMBER = new Set(["field", "variable", "property", "constant", "enum_member"]);

export function toChangeSet(raw: RawDiffResult): ChangeSet {
  const symbols: ChangedSymbol[] = [];
  const files = new Set<string>();
  for (const file of raw.files) {
    files.add(file.path);
    if (file.language && NON_CODE_LANG.has(file.language)) continue;
    for (const c of file.changes) {
      if (NON_SYMBOL.has(c.kind)) continue;
      if (NOISE_MEMBER.has(c.kind) && (c.type === "added" || c.type === "body_changed")) continue;
      const line = c.after_start_line ?? c.before_start_line;
      const name = c.new_name ?? c.name;
      symbols.push({
        ref: {
          name,
          qualifiedName: name,
          kind: c.kind,
          file: c.new_path ?? file.path,
          line: line && line > 0 ? line : undefined,
          external: false,
        },
        changeType:
          c.reconciliation === "RENAMED" ? "renamed" : (CHANGE_TYPE[c.type] ?? "unknown"),
        dependentsCount: c.dependents_count,
        oldSignature: c.old_signature,
        newSignature: c.new_signature,
      });
    }
  }
  return { base: raw.base, head: raw.head, checkpoint: raw.checkpoint, symbols, changedFiles: [...files] };
}

const SECTION_RELATION: Record<ImpactSectionName, string> = {
  callers: "CALLED_BY",
  callees: "CALLS",
  type_consumers: "USES_TYPE",
  data_flows: "DATA_FLOWS",
  co_changes: "FILE_CHANGES_WITH",
  siblings: "SIBLING",
};
const SECTION_DOMAIN: Record<ImpactSectionName, RadiusSection> = {
  callers: "callers",
  callees: "callees",
  type_consumers: "type_consumers",
  data_flows: "data_flows",
  co_changes: "co_changes",
  siblings: "siblings",
};

export function toRadiusNodes(raw: RawImpactResult, origin: string): RadiusNode[] {
  const out: RadiusNode[] = [];
  for (const section of IMPACT_SECTIONS) {
    for (const e of raw[section].entries) {
      const ep = e.endpoint;
      const qn = ep.qualified_name && ep.qualified_name.length > 0 ? ep.qualified_name : ep.name;
      const ref: SymbolRef = {
        name: ep.name,
        qualifiedName: qn,
        kind: ep.kind,
        file: ep.file_path,
        line: ep.start_line,
        external: ep.external ?? false,
      };
      const rel = e.relation?.toUpperCase();
      out.push({
        ref,
        section: SECTION_DOMAIN[section],
        relation:
          rel === "USES_TYPE" || rel === "PARAM_TYPE" || rel === "RETURNS_TYPE"
            ? rel
            : SECTION_RELATION[section],
        distance: e.depth && e.depth > 0 ? e.depth : 1,
        viaChain: e.via ? e.via.split(/\s*(?:->|,)\s*/).filter(Boolean) : [],
        originSymbols: [origin],
        isTest: isTest(ref),
      });
    }
  }
  return out;
}

/**
 * Fold the per-changed-symbol impact node lists into one blast radius.
 *  - dedupe by (file, qualifiedName): keep the SHORTEST distance, union origins
 *  - a node that is itself a changed symbol is the origin, not the blast — dropped
 *  - drop external callees (fmt.Errorf etc.) as review noise
 */
import type { BlastRadius, ChangedSymbol, RadiusNode, RadiusSection } from "./model.js";
import { symbolKey } from "./model.js";

function emptyTotals(): Record<RadiusSection, number> {
  return { callers: 0, callees: 0, type_consumers: 0, data_flows: 0, co_changes: 0, siblings: 0 };
}

function merge(a: RadiusNode, b: RadiusNode): RadiusNode {
  const origins = new Set([...a.originSymbols, ...b.originSymbols]);
  const closer = b.distance < a.distance ? b : a;
  return {
    ...closer,
    originSymbols: [...origins],
    viaChain: closer.viaChain.length > 0 ? closer.viaChain : a.viaChain,
    isTest: a.isTest || b.isTest,
  };
}

export function computeBlastRadius(
  origin: readonly ChangedSymbol[],
  nodeLists: readonly (readonly RadiusNode[])[],
): BlastRadius {
  const originKeys = new Set(origin.map((s) => symbolKey(s.ref)));
  const originNames = new Set(origin.map((s) => s.ref.qualifiedName));
  const byKey = new Map<string, RadiusNode>();

  for (const list of nodeLists) {
    for (const node of list) {
      if (node.ref.external && node.section === "callees") continue;
      const key = symbolKey(node.ref);
      if (originKeys.has(key) || originNames.has(node.ref.qualifiedName)) continue;
      const existing = byKey.get(key);
      byKey.set(key, existing ? merge(existing, node) : node);
    }
  }

  const nodes = [...byKey.values()].sort(
    (a, b) => a.distance - b.distance || a.ref.qualifiedName.localeCompare(b.ref.qualifiedName),
  );
  const sectionTotals = emptyTotals();
  for (const n of nodes) sectionTotals[n.section] += 1;
  return { origin: [...origin], nodes, sectionTotals };
}

/**
 * Scope-creep detection. The graph says what changed; the intent says what was
 * asked. A changed symbol whose name shares no vocabulary with the intent, and
 * that other code depends on, is flagged.
 *
 * Deliberately lexical, not embeddings — it has to be explainable to a reviewer
 * in one sentence: "this symbol shares no words with the ticket."
 */
import type { BlastRadius, ChangeSet, Finding, IntentModel, Severity } from "./model.js";
import { loc } from "./model.js";

const STOP = new Set([
  "the", "and", "for", "with", "add", "adds", "added", "fix", "fixes", "update", "updates",
  "change", "changes", "make", "use", "using", "support", "new", "into", "endpoint", "so",
  "that", "this", "when", "get", "set", "run", "via", "per",
]);

export function splitIdent(s: string): string[] {
  return s
    .replace(/[/\\.]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
}

function stem(w: string): string {
  return w.replace(/(ies)$/, "y").replace(/(ing|ed|ly|es|s|er|or)$/, "");
}

export function keywords(text: string): string[] {
  const out = new Set<string>();
  for (const w of splitIdent(text)) {
    if (w.length < 3 || STOP.has(w)) continue;
    const s = stem(w);
    if (s.length >= 3 && !STOP.has(s)) out.add(s);
  }
  return [...out].sort();
}

function tokens(qualifiedName: string, file: string | undefined): Set<string> {
  const parts = [
    ...splitIdent(qualifiedName),
    ...(file ? splitIdent(file.replace(/\.[a-z0-9]+$/i, "")) : []),
  ].filter((p) => !["src", "internal", "pkg", "lib", "cmd", "test", "tests"].includes(p));
  const out = new Set<string>();
  for (const p of parts) {
    if (p.length < 3 || STOP.has(p)) continue;
    out.add(stem(p));
  }
  return out;
}

function severity(deps: number): Severity {
  if (deps >= 15) return "high";
  if (deps >= 6) return "medium";
  return "low";
}

export interface ScopeOptions {
  readonly maxOverlap?: number;
  readonly minDependents?: number;
  readonly wideThreshold?: number;
}

export function detectScopeCreep(
  changeSet: ChangeSet,
  intent: IntentModel | null,
  radius: BlastRadius,
  opts: ScopeOptions = {},
): Finding[] {
  const maxOverlap = opts.maxOverlap ?? 0.15;
  const minDeps = opts.minDependents ?? 3;
  const wide = opts.wideThreshold ?? 8;
  const kw = new Set(intent?.keywords ?? []);
  const findings: Finding[] = [];

  for (const s of changeSet.symbols) {
    if (s.changeType === "added") continue;
    const t = tokens(s.ref.qualifiedName, s.ref.file);
    const shared = [...t].filter((x) => kw.has(x));
    const overlap = t.size === 0 ? 1 : shared.length / t.size;

    const keywordMiss = kw.size > 0 && overlap <= maxOverlap && s.dependentsCount >= minDeps;
    const wideReach = s.dependentsCount >= wide;
    if (!keywordMiss && !wideReach) continue;

    const trail = radius.nodes
      .filter((n) => n.section === "callers" && n.originSymbols.includes(s.ref.qualifiedName) && !n.isTest)
      .slice(0, 3)
      .map((n) => n.ref.qualifiedName);

    const reasons: string[] = [];
    if (keywordMiss) {
      reasons.push(
        shared.length === 0
          ? "no vocabulary overlap with the stated intent"
          : `weak overlap with the stated intent (only: ${shared.join(", ")})`,
      );
    }
    if (wideReach) {
      reasons.push(
        s.changeType === "signature_changed"
          ? `signature changed with ${s.dependentsCount} dependents — run tests first`
          : `wide-reaching change: ${s.dependentsCount} dependents`,
      );
    }

    findings.push({
      symbol: s.ref,
      severity: severity(s.dependentsCount),
      reason: reasons.join("; "),
      dependentsCount: s.dependentsCount,
      evidence: [
        intent ? `intent (${intent.source}): "${intent.text.slice(0, 90)}"` : "no stated intent",
        `changed — ${s.changeType.replace("_", " ")}, ${s.dependentsCount} dependents` +
          (loc(s.ref) ? ` — ${loc(s.ref)}` : ""),
        ...(trail.length ? [`reaches ${trail.join(" → ")}`] : []),
      ],
    });
  }

  return findings.sort(
    (a, b) =>
      ({ high: 3, medium: 2, low: 1 })[b.severity] - ({ high: 3, medium: 2, low: 1 })[a.severity] ||
      b.dependentsCount - a.dependentsCount,
  );
}

/**
 * Pick the smallest set of tests that exercises the change.
 *  1. every test node in the radius is a candidate
 *  2. score by proximity (closer = higher; direct caller bonus)
 *  3. greedily add until every changed callable is covered
 *  4. changed callables no test reaches = explicit coverage gaps
 *  5. synthesise the run command for the detected framework
 */
import type { BlastRadius, ChangedSymbol, SymbolRef, TestCandidate, TestPlan } from "./model.js";

function framework(ref: SymbolRef): string {
  const f = (ref.file ?? "").replace(/\\/g, "/");
  if (/_test\.go$/.test(f)) return "go";
  if (/\.(test|spec)\.[cm]?[jt]sx?$/.test(f)) return "vitest";
  if (/(^|\/)test_.*\.py$|_test\.py$/.test(f)) return "pytest";
  return "unknown";
}

function isFileName(ref: SymbolRef): boolean {
  return /\.[cm]?[jt]sx?$/.test(ref.name) || /_test\.(go|py)$/.test(ref.name) || ref.name === ref.file;
}

function packageDir(file: string): string {
  const i = file.replace(/\\/g, "/").lastIndexOf("/");
  return i === -1 ? "." : file.replace(/\\/g, "/").slice(0, i);
}

function command(fw: string, selected: readonly TestCandidate[]): string | null {
  if (selected.length === 0) return null;
  const files = [...new Set(selected.map((t) => t.ref.file).filter((f): f is string => !!f))];
  const names = [
    ...new Set(selected.filter((t) => !isFileName(t.ref)).map((t) => t.ref.name)),
  ];
  switch (fw) {
    case "go": {
      const dirs = [...new Set(files.map(packageDir))].map((d) => `./${d}/...`);
      return names.length
        ? `go test -run '^(${names.join("|")})$' ${dirs.join(" ")}`
        : `go test ${dirs.join(" ")}`;
    }
    case "vitest":
      return names.length
        ? `npx vitest run ${files.join(" ")} -t "${names.join("|")}"`
        : `npx vitest run ${files.join(" ")}`;
    case "pytest":
      return `pytest ${selected.map((t) => (t.ref.file && !isFileName(t.ref) ? `${t.ref.file}::${t.ref.name}` : (t.ref.file ?? t.ref.name))).join(" ")}`;
    default:
      return null;
  }
}

const CALLABLE = new Set(["function", "method", "constructor"]);

export function selectTests(
  radius: BlastRadius,
  origin: readonly ChangedSymbol[],
  maxTests = 12,
): TestPlan {
  const testNodes = radius.nodes.filter((n) => n.isTest);
  const fw = (() => {
    const tally = new Map<string, number>();
    for (const n of testNodes) {
      const f = framework(n.ref);
      if (f !== "unknown") tally.set(f, (tally.get(f) ?? 0) + 1);
    }
    return [...tally.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "unknown";
  })();

  const ranked = testNodes
    .map((n) => ({
      n,
      score: 1 / (1 + n.distance) + (n.section === "callers" && n.distance <= 1 ? 0.5 : 0),
    }))
    .sort((a, b) => b.score - a.score);

  const behavioural = origin
    .filter((s) => CALLABLE.has(s.ref.kind ?? "") && s.changeType !== "added")
    .map((s) => s.ref.qualifiedName);
  const covered = new Set<string>();
  const selected: TestCandidate[] = [];
  for (const { n } of ranked) {
    if (selected.length >= maxTests) break;
    const isNew = n.originSymbols.some((s) => !covered.has(s));
    if (!isNew && selected.length > 0) continue;
    for (const s of n.originSymbols) covered.add(s);
    selected.push({ ref: n.ref, distance: n.distance, covers: [...n.originSymbols] });
  }

  return {
    framework: fw,
    selected,
    command: command(fw, selected),
    coverageGaps: behavioural.filter((s) => !covered.has(s)),
  };
}

/** AnalysisReport → a Markdown review comment. Pure. */
import type { AnalysisReport } from "./model.js";
import { loc } from "./model.js";

const SEV = { high: "🔴", medium: "🟠", low: "🟡" } as const;

function short(ref: string): string {
  return /^[0-9a-f]{40}$/i.test(ref) ? ref.slice(0, 7) : ref;
}

export function renderMarkdown(r: AnalysisReport): string {
  const o: string[] = [];
  const s = r.radius;

  o.push("<!-- blast-radius -->");
  o.push("## 🧨 Blast Radius");
  o.push("");
  const parts = [
    `**${s.nodes.length} node${s.nodes.length === 1 ? "" : "s"}**`,
    `${r.changedSymbols.length} changed`,
    r.findings.length ? `**${r.findings.length} scope finding${r.findings.length === 1 ? "" : "s"}**` : "0 scope findings",
    `**${r.testPlan.selected.length} test${r.testPlan.selected.length === 1 ? "" : "s"}**` +
      (r.testPlan.coverageGaps.length ? ` (${r.testPlan.coverageGaps.length} gap${r.testPlan.coverageGaps.length === 1 ? "" : "s"})` : ""),
  ];
  o.push(parts.join(" · "));
  o.push("");

  if (r.intent) {
    o.push(`> **Intent** — _${JSON.stringify(r.intent.text.slice(0, 160))}_  `);
    o.push(`> source: \`${r.intent.source}\`` + (r.range.checkpoint ? ` · \`${r.range.checkpoint}\`` : ""));
  } else {
    o.push("> **Intent** — none found. Scope drift can't be judged; showing radius + tests only.");
  }
  o.push("");

  if (r.findings.length) {
    o.push(`### ⚠️ Scope check — ${r.findings.length} change(s) look outside the ask`);
    o.push("");
    o.push("| | Changed symbol | Why | Dependents |");
    o.push("|--|--|--|--|");
    for (const f of r.findings) {
      o.push(`| ${SEV[f.severity]} | \`${f.symbol.qualifiedName}\`${loc(f.symbol) ? ` \`${loc(f.symbol)}\`` : ""} | ${f.reason} | ${f.dependentsCount} |`);
    }
    o.push("");
    o.push("<details><summary>Evidence</summary>", "");
    for (const f of r.findings) {
      o.push(`**\`${f.symbol.qualifiedName}\`**`);
      for (const e of f.evidence) o.push(`- ${e}`);
      o.push("");
    }
    o.push("</details>", "");
  } else if (r.intent) {
    o.push("### ✅ Scope check — every change maps to the stated intent", "");
  }

  const tp = r.testPlan;
  if (tp.selected.length) {
    const cover = tp.coverageGaps.length === 0 ? "covers every changed symbol" : `covers all but ${tp.coverageGaps.length}`;
    o.push(`### 🧪 Recommended tests — ${tp.selected.length}, ${cover}`, "");
    if (tp.command) o.push("```bash", tp.command, "```", "");
    o.push("<details><summary>Why these tests</summary>", "");
    o.push("| Test | Covers | Distance |", "|--|--|--|");
    for (const t of tp.selected) {
      o.push(`| \`${t.ref.name}\` | ${t.covers.map((c) => `\`${c}\``).join(", ")} | ${t.distance} |`);
    }
    if (tp.coverageGaps.length) {
      o.push("", `**No test reaches:** ${tp.coverageGaps.map((g) => `\`${g}\``).join(", ")} — verify manually.`);
    }
    o.push("", "</details>", "");
  } else {
    o.push("### 🧪 Recommended tests — none found in the blast radius", "");
  }

  const byRel: Record<string, number> = {};
  for (const n of s.nodes) byRel[n.relation] = (byRel[n.relation] ?? 0) + 1;
  o.push(
    `<details><summary>Full blast radius — ${s.nodes.length} nodes</summary>`,
    "",
    Object.entries(byRel).sort((a, b) => b[1] - a[1]).map(([k, v]) => `\`${k}\` ${v}`).join(" · "),
    "",
    "| Node | Relation | Dist | From |",
    "|--|--|--|--|",
  );
  for (const n of s.nodes.slice(0, 50)) {
    o.push(`| \`${n.ref.qualifiedName}\`${n.isTest ? " 🧪" : ""} | \`${n.relation}\` | ${n.distance} | ${n.originSymbols.map((x) => `\`${x}\``).join(", ")} |`);
  }
  o.push("", "</details>", "");

  o.push("---");
  o.push(`<sub>Generated by Blast Radius from Entire Graph · \`${short(r.range.base)}\`..\`${short(r.range.head)}\` · every row is backed by the graph path behind it</sub>`);
  return o.join("\n");
}

export function renderJson(r: AnalysisReport): string {
  return JSON.stringify(r, null, 2);
}

/** The one seam that matters: everything Blast Radius needs from Entire Graph. */
import type { ChangeSet, RadiusNode } from "./domain/model.js";

export interface CommitRange {
  readonly base: string;
  readonly head: string;
}

export interface ImpactQuery {
  readonly name: string;
  readonly file: string | undefined;
}

export interface GraphProvider {
  readonly kind: string;
  diff(range: CommitRange): Promise<ChangeSet>;
  impact(q: ImpactQuery): Promise<{ nodes: RadiusNode[]; disambiguation: boolean }>;
}

/** FixtureGraphProvider — recorded `entire graph` JSON from a directory. */
import { readFile } from "node:fs/promises";
import path from "node:path";
import { toChangeSet, toRadiusNodes } from "../domain/graph-mapping.js";
import { rawDiffResult, rawImpactResult } from "../domain/graph-schema.js";
import type { ChangeSet } from "../domain/model.js";
import type { CommitRange, GraphProvider, ImpactQuery } from "../ports.js";

const sanitize = (n: string) => n.replace(/[^A-Za-z0-9._-]+/g, "_");

export class FixtureGraphProvider implements GraphProvider {
  readonly kind = "fixture";
  constructor(private readonly dir: string) {}

  private async json(file: string): Promise<unknown | null> {
    try {
      return JSON.parse(await readFile(path.resolve(this.dir, file), "utf8"));
    } catch {
      return null;
    }
  }

  async diff(_range: CommitRange): Promise<ChangeSet> {
    const raw = await this.json("diff.json");
    if (raw === null) throw new Error(`fixture diff.json not found in ${this.dir}`);
    return toChangeSet(rawDiffResult.parse(raw));
  }

  async impact(q: ImpactQuery): Promise<{ nodes: ReturnType<typeof toRadiusNodes>; disambiguation: boolean }> {
    for (const cand of [
      `impact-${sanitize(q.name)}.json`,
      `impact-${sanitize(q.name.split(".").pop() ?? q.name)}.json`,
    ]) {
      const raw = await this.json(cand);
      if (raw === null) continue;
      const parsed = rawImpactResult.parse(raw);
      return { nodes: toRadiusNodes(parsed, q.name), disambiguation: parsed.disambiguation_required };
    }
    return { nodes: [], disambiguation: false };
  }
}

/** EntireGraphCliProvider — shells out to the real `entire graph` binary. */
import { execa } from "execa";
import { toChangeSet, toRadiusNodes } from "../domain/graph-mapping.js";
import { rawDiffResult, rawImpactResult } from "../domain/graph-schema.js";
import type { ChangeSet } from "../domain/model.js";
import type { CommitRange, GraphProvider, ImpactQuery } from "../ports.js";

export interface CliOptions {
  /** how to invoke the graph: `["entire","graph"]` or `["/path/to/entire-graph"]`. */
  readonly argv0: readonly string[];
  readonly repo: string;
  readonly profile?: "fast" | "full";
  readonly timeoutMs?: number;
}

export class EntireGraphCliProvider implements GraphProvider {
  readonly kind = "entire-graph-cli";
  constructor(private readonly opts: CliOptions) {}

  private async run(args: string[]): Promise<unknown> {
    const [bin, ...pre] = this.opts.argv0;
    const r = await execa(bin!, [...pre, ...args], {
      timeout: this.opts.timeoutMs ?? 240_000,
      stripFinalNewline: true,
    });
    return JSON.parse(String(r.stdout ?? ""));
  }

  async diff(range: CommitRange): Promise<ChangeSet> {
    const raw = await this.run([
      "diff", "--repo", this.opts.repo, "--base", range.base, "--head", range.head, "--json",
    ]);
    return toChangeSet(rawDiffResult.parse(raw));
  }

  async impact(q: ImpactQuery): Promise<{ nodes: ReturnType<typeof toRadiusNodes>; disambiguation: boolean }> {
    const args = [
      "impact", "--repo", this.opts.repo, "--symbol", q.name,
      "--format", "json", "--depth", "2", "--profile", this.opts.profile ?? "full",
    ];
    if (q.file) args.push("--file", q.file);
    const raw = await this.run(args);
    const parsed = rawImpactResult.parse(raw);
    return { nodes: toRadiusNodes(parsed, q.name), disambiguation: parsed.disambiguation_required };
  }
}

/**
 * Resolve the stated intent of a change.
 *  1. the Entire-Checkpoint trailer on the head commit + its captured prompt
 *     (.entire/intent/<id>.json, or the checkpoint's own text)
 *  2. the commit subject/body as a fallback
 */
import { readFile } from "node:fs/promises";
import path from "node:path";
import { execa } from "execa";
import { keywords } from "../domain/scope-creep.js";
import type { IntentModel } from "../domain/model.js";

const TRAILER = /Entire-Checkpoint:\s*([A-Za-z0-9._-]+)/;

async function gitBody(repo: string, ref: string): Promise<string> {
  try {
    const { stdout } = await execa("git", ["-C", repo, "log", "-1", "--format=%B", ref]);
    return stdout;
  } catch {
    return "";
  }
}

async function capturedIntent(repo: string, id: string): Promise<string | null> {
  for (const rel of [`.entire/intent/${id}.json`, `.entire/intents/${id}.json`]) {
    try {
      const j = JSON.parse(await readFile(path.resolve(repo, rel), "utf8")) as Record<string, unknown>;
      const t = (j.prompt ?? j.body ?? j.title ?? j.summary) as string | undefined;
      if (t) return t;
    } catch {
      /* next */
    }
  }
  return null;
}

export interface IntentContext {
  readonly repo: string;
  readonly head: string;
  readonly prTitle?: string | undefined;
  readonly prBody?: string | undefined;
}

export async function resolveIntent(
  ctx: IntentContext,
): Promise<{ intent: IntentModel | null; checkpoint: string | undefined }> {
  const body = await gitBody(ctx.repo, ctx.head);
  const id = TRAILER.exec(body)?.[1];

  if (id) {
    const captured = await capturedIntent(ctx.repo, id);
    const text = captured ?? body.split("\n").filter((l) => !TRAILER.test(l)).join("\n").trim();
    if (text) {
      return { intent: { source: "checkpoint-trailer", text, keywords: keywords(text) }, checkpoint: id };
    }
  }

  const pr = `${ctx.prTitle ?? ""}\n${ctx.prBody ?? ""}`.trim();
  if (pr) return { intent: { source: "pr-body", text: pr, keywords: keywords(pr) }, checkpoint: id };

  const subject = body.split("\n")[0]?.trim();
  if (subject) {
    return { intent: { source: "commit-message", text: subject, keywords: keywords(subject) }, checkpoint: id };
  }
  return { intent: null, checkpoint: id };
}

/**
 * The `review` use-case — the pipeline, spelled out.
 *   diff → impact per changed symbol → fold → { scope check · test selection } → report
 * Depends only on a GraphProvider + an intent resolver.
 */
import { computeBlastRadius } from "./domain/blast-radius.js";
import type { AnalysisReport } from "./domain/model.js";
import { renderMarkdown } from "./domain/render.js";
import { detectScopeCreep, type ScopeOptions } from "./domain/scope-creep.js";
import { selectTests } from "./domain/test-select.js";
import { resolveIntent, type IntentContext } from "./adapters/intent.js";
import type { CommitRange, GraphProvider } from "./ports.js";

export interface ReviewRequest {
  readonly range: CommitRange;
  readonly repo: string;
  readonly prTitle?: string | undefined;
  readonly prBody?: string | undefined;
  readonly scope?: ScopeOptions;
  readonly log?: (msg: string) => void;
}

export async function runReview(
  graph: GraphProvider,
  req: ReviewRequest,
): Promise<{ report: AnalysisReport; markdown: string }> {
  const log = req.log ?? (() => {});

  const changeSet = await graph.diff(req.range);
  log(`${changeSet.symbols.length} changed symbol(s) across ${changeSet.changedFiles.length} file(s)`);

  const impacts = await Promise.all(
    changeSet.symbols.map((s) =>
      graph.impact({ name: s.ref.qualifiedName, file: s.ref.file }).catch((e) => {
        log(`impact skipped for ${s.ref.qualifiedName}: ${(e as Error).message}`);
        return { nodes: [], disambiguation: false };
      }),
    ),
  );
  const radius = computeBlastRadius(changeSet.symbols, impacts.map((i) => i.nodes));
  log(`blast radius: ${radius.nodes.length} node(s)`);

  const intentCtx: IntentContext = {
    repo: req.repo,
    head: req.range.head,
    prTitle: req.prTitle,
    prBody: req.prBody,
  };
  const { intent, checkpoint } = await resolveIntent(intentCtx);
  log(intent ? `intent from ${intent.source}` : "no stated intent found");

  const findings = detectScopeCreep(changeSet, intent, radius, req.scope);
  const testPlan = selectTests(radius, changeSet.symbols);

  const report: AnalysisReport = {
    schemaVersion: "1.0.0",
    generatedAt: new Date().toISOString(),
    range: { base: req.range.base, head: req.range.head, checkpoint: checkpoint ?? changeSet.checkpoint },
    intent,
    changedSymbols: changeSet.symbols,
    radius,
    findings,
    testPlan,
  };
  return { report, markdown: renderMarkdown(report) };
}

#!/usr/bin/env node
/** Blast Radius CLI — arg parsing → composition → runReview. */
import { writeFile } from "node:fs/promises";
import { Command } from "commander";
import { EntireGraphCliProvider } from "./adapters/cli.js";
import { FixtureGraphProvider } from "./adapters/fixture.js";
import { renderJson } from "./domain/render.js";
import { runReview } from "./review.js";
import type { GraphProvider } from "./ports.js";

const program = new Command();
program.name("blast-radius").description("Impact-aware PR review powered by Entire Graph").version("0.1.0");

program
  .command("review")
  .option("--base <ref>", "base revision", "HEAD~1")
  .option("--head <ref>", "head revision", "HEAD")
  .option("--repo <path>", "repository path", ".")
  .option("--fixture <dir>", "use recorded entire graph JSON instead of the binary")
  .option("--entire-graph <cmd>", "how to invoke the graph, space-separated", "entire graph")
  .option("--profile <p>", "fast | full", "full")
  .option("--format <fmt>", "markdown | json", "markdown")
  .option("--out <file>", "write here instead of stdout")
  .option("--pr-title <s>", "PR title (intent fallback)")
  .option("--pr-body <s>", "PR body (intent fallback)")
  .option("--dependents-threshold <n>", "wide-reaching-change threshold", (v) => parseInt(v, 10))
  .option("--fail-on-findings", "exit non-zero when scope findings exist")
  .option("--quiet", "suppress progress logs")
  .action(async (opts) => {
    const log = opts.quiet ? undefined : (m: string) => process.stderr.write(`[blast-radius] ${m}\n`);

    const graph: GraphProvider = opts.fixture
      ? new FixtureGraphProvider(opts.fixture)
      : new EntireGraphCliProvider({
          argv0: String(opts.entireGraph).split(/\s+/),
          repo: opts.repo,
          profile: opts.profile === "fast" ? "fast" : "full",
        });

    try {
      const { report, markdown } = await runReview(graph, {
        range: { base: opts.base, head: opts.head },
        repo: opts.repo,
        prTitle: opts.prTitle,
        prBody: opts.prBody,
        scope: opts.dependentsThreshold ? { wideThreshold: opts.dependentsThreshold } : {},
        log,
      });

      const body = opts.format === "json" ? renderJson(report) : markdown;
      if (opts.out) {
        await writeFile(opts.out, body, "utf8");
        log?.(`wrote ${opts.out}`);
      } else {
        process.stdout.write(body + "\n");
      }

      if (opts.failOnFindings && report.findings.length > 0) {
        process.stderr.write(`\n✖ ${report.findings.length} scope finding(s)\n`);
        process.exitCode = 1;
      }
    } catch (e) {
      process.stderr.write(`\n✖ ${(e as Error).message}\n`);
      process.exitCode = 2;
    }
  });

program.parseAsync().catch((e) => {
  process.stderr.write(`\n✖ ${(e as Error).message}\n`);
  process.exitCode = 2;
});

