302	      );
303	    }
304	    lines.push("", "</details>");
305	    return lines.join("\n");
306	  }
307	
308	  private radiusSection(r: AnalysisReport): string {
309	    const rel = r.radiusSummary.byRelation;
310	    const relSummary = Object.entries(rel)
311	      .sort((a, b) => b[1] - a[1])
312	      .map(([k, v]) => `\`${k}\` ${v}`)
