330	      );
331	    }
332	    if (r.radiusNodes.length > 60) {
333	      lines.push(`| _…and ${r.radiusNodes.length - 60} more (see \`--format json\`)_ | | | |`);
334	    }
335	    lines.push("", "</details>");
336	    return lines.join("\n");
337	  }
338	
339	  private footer(r: AnalysisReport): string {
340	    const tool = this.opts.toolUrl ?? "Blast Radius";
341	    const base = shortSha(r.range.base);
342	    const head = shortSha(r.range.head);
