358	    const anchor = line ? `#L${line}` : "";
359	    return `[${label}](${this.opts.repoBlobUrlBase}/${file}${anchor})`;
360	  }
361	}
362	
363	/* --------------------------------------------------------------- mermaid --- */
364	
365	function mermaidIds() {
366	  const map = new Map<string, string>();
